SOURCES={'ema_dashboard.py': '"""Notebook presentation only: never imports torch or changes worker/config state."""\nimport html\nimport json\nimport math\nimport subprocess\nimport time\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\n\nSTAGES = {\'starting\': \'시작 준비\', \'load_gpu_data\': \'데이터 → GPU\', \'train\': \'학습\',\n          \'validation\': \'검증\', \'epoch_complete\': \'에폭 완료\', \'paused\': \'체크포인트 저장 · 일시정지\',\n          \'training_complete_no_test\': \'학습 완료 · test 미실행\', \'evaluate_RR\': \'RR 평가\',\n          \'evaluate_FR\': \'FR 평가\', \'evaluation_complete\': \'평가 완료\', \'error\': \'오류\',\n          \'interrupted\': \'중단\', \'idle\': \'대기\'}\nPHASES = {\'probe\':\'β 후보 점검 · validation만 사용\',\'calibrate\': \'손실 크기 확인 · λ 후보 고정\', \'smoke\': \'소량 실행 · 저장/재개 점검\',\n          \'sweep\': \'β 후보 점검 · validation만 사용\', \'select\': \'λ 선택 · 최종 설정 고정\',\n          \'final_train\': \'본 학습 · 3개 seed\', \'final_test\': \'최종 RR/FR 평가\'}\n\ndef esc(value):\n    return html.escape(str(value), quote=True)\n\ndef number(value, digits=4):\n    try:\n        value = float(value)\n        return f\'{value:.{digits}g}\' if math.isfinite(value) else \'—\'\n    except (TypeError, ValueError):\n        return \'—\'\n\ndef progress(value):\n    try:\n        value = float(value)\n        if not math.isfinite(value): return \'<span class="muted">측정 대기</span>\'\n    except (TypeError, ValueError):\n        return \'<span class="muted">—</span>\'\n    value = max(0., min(100., value))\n    return f\'<div class="bar"><i style="width:{value:.1f}%"></i></div><small>{value:.1f}%</small>\'\n\ndef render(phase, rows, note=\'\', data_rows=(), gpu_stats=None, updated=\'\'):\n    gpu_stats = gpu_stats or {}\n    body, metric_body = [], []\n    for gpu in (0, 1):\n        row = rows.get(gpu, {})\n        v = row.get(\'status\', {})\n        stage = v.get(\'stage\', \'idle\')\n        epoch, epochs = v.get(\'epoch\'), row.get(\'epochs\')\n        batch, batches = v.get(\'batch\'), v.get(\'batches\')\n        fraction = None\n        if stage == \'train\' and batches:\n            fraction = 100 * batch / batches if batch is not None else None\n        elif stage in (\'validation\', \'epoch_complete\', \'training_complete_no_test\'):\n            fraction = 100\n        elif stage.startswith(\'evaluate_\') and v.get(\'scenes\'):\n            fraction = 100 * v.get(\'scene\', 0) / v[\'scenes\']\n        elif stage == \'evaluation_complete\':\n            fraction = 100\n        unit = \'장면\' if stage.startswith(\'evaluate_\') else \'배치\'\n        count = (f"{v.get(\'scene\', \'—\')}/{v.get(\'scenes\', \'—\')}" if unit == \'장면\'\n                 else f\'{batch}/{batches}\' if stage == \'train\' and batches else \'—\')\n        epoch_text = f\'{epoch}/{epochs}\' if epoch is not None and epochs else \'—\'\n        # On validation/terminal reports, loss/metrics may refer to the last observed report.\n        metrics = row.get(\'metrics\', {})\n        allocated = number(v.get(\'allocated_gib\'), 3)\n        peak = number(v.get(\'peak_gib\'), 3)\n        stats = gpu_stats.get(gpu, {})\n        device = f"{number(stats.get(\'used_gib\'), 3)} / {number(stats.get(\'total_gib\'), 3)} GiB"\n        util = number(stats.get(\'utilization\'), 3)\n        eta = v.get(\'train_eta_kst\')\n        try: eta = datetime.fromisoformat(eta).strftime(\'%m/%d %H:%M:%S\') if eta else \'측정 대기\'\n        except (ValueError, TypeError): eta = \'측정 대기\'\n        if stage in (\'training_complete_no_test\', \'evaluation_complete\'): eta = \'완료\'\n        elif stage in (\'paused\', \'error\', \'interrupted\', \'idle\') or stage.startswith(\'evaluate_\'): eta = \'—\'\n        badge = \'bad\' if stage in (\'error\', \'interrupted\') else \'good\' if stage in (\'training_complete_no_test\', \'evaluation_complete\') else \'\'\n        error = row.get(\'error\') or \'—\'\n        body.append(f\'\'\'<tr><td><b>GPU {gpu} · {esc(row.get(\'label\', \'baseline\' if gpu == 0 else \'spectral\'))}</b>\n          <small>{esc(row.get(\'context\', \'작업 대기\'))}</small><small>대기 작업 {esc(row.get(\'queued\', 0))}개</small></td>\n          <td><span class="badge {badge}">{esc(STAGES.get(stage, stage))}</span></td>\n          <td>{esc(epoch_text)}</td><td>{progress(fraction)}<small>{unit} {esc(count)}</small></td>\n          <td>{number(row.get(\'throughput\'), 4)}</td>\n          <td>{allocated} / {peak}<small>장치 {device}</small><small>사용률 {util}%</small></td>\n          <td class="error">{esc(error)}</td></tr>\'\'\')\n        metric_body.append(f\'<tr><td><b>GPU {gpu} · {esc(row.get("label", "baseline" if gpu == 0 else "spectral"))}</b></td>\' +\n                           \'\'.join(f\'<td>{number(metrics.get(key), 5)}</td>\' for key in\n                           (\'train_mse\', \'ema_updates\', \'val_mse\', \'val_psnr\', \'val_sam\')) +\n                           f\'<td>{esc(eta)}<small>KST · 학습/검증/저장</small></td></tr>\')\n    dataset = \'\'\n    if data_rows:\n        dataset = \'<details><summary>데이터 확인 결과 · 상세 수치/해시는 data_manifest.json</summary><table><tr><th>분할</th><th>전체 / 사용 장면·패치</th><th>LMS 크기 (NCHW)</th><th>검사</th></tr>\'\n        for split, info in data_rows:\n            shape = info[\'arrays\'][\'lms\'][\'shape\']\n            dataset += f\'<tr><td>{esc(split)}</td><td>{shape[0]:,} / {info["used_samples"]:,}</td><td>{esc(" × ".join(map(str, shape)))}</td><td>유한값 · 범위 · SHA-256 확인</td></tr>\'\n        dataset += \'</table></details>\'\n    return \'\'\'<style>\n      .spectral-dashboard {font-family:system-ui,-apple-system,"Malgun Gothic",sans-serif;color:#172b4d;background:#fff;border:1px solid #dce4ef;border-radius:12px;padding:18px;margin:12px 0;font-size:13px;line-height:1.5}\n      .spectral-dashboard h3 {font-size:18px;margin:0 0 5px;color:#172b4d}.spectral-dashboard h4 {font-size:13px;margin:16px 0 0}.spectral-dashboard .muted,.spectral-dashboard small{color:#66758b}.spectral-dashboard small{display:block;font-size:11px}\n      .spectral-dashboard .scroll {overflow-x:auto}.spectral-dashboard table{width:100%;border-collapse:collapse;margin:12px 0;white-space:nowrap}\n      .spectral-dashboard th{background:#edf2f8;color:#34465e;font-weight:600;text-align:left;padding:10px 8px}\n      .spectral-dashboard td{padding:12px 8px;border-bottom:1px solid #e5ebf3;vertical-align:top}.spectral-dashboard tr:nth-child(even) td{background:#f8fafc}\n      .spectral-dashboard .badge{display:inline-block;padding:3px 7px;background:#eaf2ff;color:#2455a4;border-radius:5px}.spectral-dashboard .good{background:#e8f6ed;color:#237746}.spectral-dashboard .bad{background:#ffebeb;color:#a52626}\n      .spectral-dashboard .bar{width:92px;height:6px;background:#e1e8f2;border-radius:3px;overflow:hidden;margin:6px 0}.spectral-dashboard .bar i{display:block;height:100%;background:#427ee8}\n      .spectral-dashboard .notice{padding:9px 12px;background:#f0f5fb;border-radius:7px;margin:10px 0;white-space:pre-wrap;overflow-wrap:anywhere}\n      .spectral-dashboard .error{max-width:200px;min-width:40px;white-space:normal;overflow-wrap:anywhere;color:#a52626}.spectral-dashboard summary{cursor:pointer}\n      </style>\'\'\' + f\'\'\'<section class="spectral-dashboard"><h3>EMA_1st · {esc(PHASES.get(phase, phase))}</h3>\n      <span class="muted">K=4 · QuickBird · GPU0 baseline / GPU1 spectral · 갱신 {esc(updated or \'—\')}</span>\n      <div class="notice">{esc(note or \'준비 중\')}</div>{dataset}<div class="scroll"><table><thead><tr>\n      <th>실험</th><th>상태</th><th>에폭</th><th>현재 에폭 / 평가 진행</th>\n      <th>패치/초</th><th>모델 할당 / 최대 GiB</th><th>오류</th>\n      </tr></thead><tbody>{\'\'.join(body)}</tbody></table></div>\n      <h4>손실 · 최근 완료 Validation · 학습 종료 예상</h4><div class="scroll"><table><thead><tr>\n      <th>실험</th><th>Train MSE</th><th>EMA 갱신</th><th>Val MSE</th><th>Val PSNR</th><th>Val SAM</th><th>종료 예상</th>\n      </tr></thead><tbody>{\'\'.join(metric_body)}</tbody></table></div>\n      <small>손실은 최근 worker 보고값입니다. Validation은 최근 완료 에폭 값이며 best 값과 다를 수 있습니다. 상세 ERGAS·SCC·Q2n은 history.json에 기록됩니다.</small>\n      <small>패치/초는 같은 에폭의 두 학습 보고 사이에서 실측합니다. 첫 보고 전에는 —로 표시합니다. 장치 메모리는 다른 프로세스도 포함합니다.</small>\n      <small>종료 예상에는 대기 작업·test 평가·그림·ZIP 시간이 포함되지 않습니다. 상태 표는 약 5초마다, worker 손실/진행 보고는 약 20초마다 갱신됩니다.</small>\n      </section>\'\'\'\n\nclass Dashboard:\n    def __init__(self, phase, root):\n        self.phase, self.root = phase, Path(root)\n        self.rows = {0: {}, 1: {}}\n        self.data_rows, self.note, self.gpu_stats = [], \'데이터 검사 준비 중\', {}\n        self.handle = None\n        self.last_gpu = self.last_plain = 0.\n\n    def data_checked(self, split, info):\n        self.data_rows.append((split, info))\n        self.note = f\'{split} 검사 완료 · 전체 {info["arrays"]["lms"]["shape"][0]:,} / 사용 {info["used_samples"]:,}개\'\n        self.refresh()\n\n    def starting(self, job, queued):\n        g, config = job[\'gpu\'], job[\'config\']\n        self.rows[g] = {\'label\': job[\'label\'], \'epochs\': config[\'epochs\'], \'queued\': queued,\n                        \'samples\': config[\'data\'][\'train\'][\'used_samples\'], \'batch_size\': config[\'batch\'],\n                        \'context\': f\'{job["folder"].parent.name} · β={config["weight"]:g} · {job["folder"].parent.parent.name}\',\n                        \'status\': {\'stage\': \'starting\'}, \'metrics\': {}, \'throughput\': None}\n\n    def observe(self, gpu, value):\n        row = self.rows[gpu]\n        previous = row.get(\'status\', {})\n        row[\'throughput\'] = None\n        if value.get(\'stage\') == previous.get(\'stage\') == \'train\' and value.get(\'epoch\') == previous.get(\'epoch\'):\n            try:\n                seconds = (datetime.fromisoformat(value[\'updated_kst\']) - datetime.fromisoformat(previous[\'updated_kst\'])).total_seconds()\n                # Report batch is an effective group; cap the final partial group\'s sample count.\n                count = row[\'samples\']\n                delta = min(value[\'batch\'] * row[\'batch_size\'], count) - min(previous[\'batch\'] * row[\'batch_size\'], count)\n                if seconds > 0 and delta > 0: row[\'throughput\'] = delta / seconds\n            except (ValueError, KeyError, TypeError): pass\n        row[\'status\'] = value\n        for key in (\'train_mse\', \'ema_updates\', \'val_mse\', \'val_psnr\', \'val_sam\'):\n            if key in value: row[\'metrics\'][key] = value[key]\n\n    def finish(self, job, returncode=0, skipped=False):\n        g = job[\'gpu\']\n        row = self.rows[g]\n        if returncode:\n            row[\'status\'] = {**row.get(\'status\', {}), \'stage\': \'error\'}\n            row[\'error\'] = f\'종료 코드 {returncode} · {job["folder"].relative_to(self.root)}/worker.log 확인\'\n        else:\n            marker = \'evaluation_complete.json\' if job[\'config\'][\'job_type\'] == \'test\' else \'training_complete.json\'\n            complete = (job[\'folder\'] / marker).is_file()\n            name = (\'evaluation_complete\' if job[\'config\'][\'job_type\'] == \'test\' else \'training_complete_no_test\') if complete else \'paused\'\n            row[\'status\'] = {**row.get(\'status\', {}), \'stage\': name}\n            if complete and job[\'config\'][\'job_type\'] != \'test\': row[\'status\'][\'epoch\'] = job[\'config\'][\'epochs\']\n            if skipped: row[\'context\'] += \' · 저장된 완료 결과 확인\'\n        row[\'throughput\'] = None\n\n    def refresh(self, note=None, persist=True):\n        if note is not None: self.note = note\n        now = time.monotonic()\n        if now - self.last_gpu >= 5:\n            self.last_gpu = now\n            try:\n                raw = subprocess.check_output([\'nvidia-smi\', \'--query-gpu=index,memory.used,memory.total,utilization.gpu\',\n                                               \'--format=csv,noheader,nounits\'], text=True, stderr=subprocess.DEVNULL, timeout=2)\n                self.gpu_stats = {}\n                for line in raw.splitlines():\n                    gpu, used, total, utilization = map(float, line.split(\',\'))\n                    self.gpu_stats[int(gpu)] = {\'used_gib\': used / 1024, \'total_gib\': total / 1024, \'utilization\': utilization}\n            except (OSError, ValueError, subprocess.SubprocessError): self.gpu_stats = {}\n        value = render(self.phase, self.rows, self.note, self.data_rows, self.gpu_stats,\n                       datetime.now(timezone(timedelta(hours=9))).strftime(\'%m/%d %H:%M:%S KST\'))\n        # Snapshot file is supplementary; a presentation failure must not interrupt training.\n        if persist:\n            try: (self.root / \'live_dashboard.html\').write_text(value, encoding=\'utf-8\')\n            except OSError: pass\n        try:\n            from IPython import get_ipython\n            from IPython.display import HTML, display\n            if get_ipython() is None: raise ImportError(\'plain Python\')\n            if self.handle is None:\n                self.handle = display(HTML(value), display_id=True)\n                if self.handle is None: raise ImportError(\'no display update handle\')\n            else: self.handle.update(HTML(value))\n        except Exception:\n            if now - self.last_plain >= 20:\n                self.last_plain = now\n                print(self.note + \' | \' + \' | \'.join(f\'GPU{g} {r.get("label", "대기")}: {STAGES.get(r.get("status", {}).get("stage", "idle"), "대기")}\' for g, r in self.rows.items()), flush=True)\n', 'ema_worker.py': '"""SpectralLoss_1st worker derived from the validated A/A harness; FP32 fixed baseline."""\nimport os\nos.environ.setdefault(\'CUBLAS_WORKSPACE_CONFIG\', \':4096:8\')\nimport argparse, hashlib, json, math, random, signal, time\nfrom datetime import datetime, timedelta, timezone\nfrom pathlib import Path\nimport numpy as np\nimport h5py\nimport torch\nfrom torch.nn import functional as F\nfrom spectral_loss import EPS, spectral_components\nfrom ema_core import EMA\n\nSTOP = False\nKST = timezone(timedelta(hours=9))\nKEYS = (\'pan\', \'lms\', \'ms\', \'gt\')\n\ndef stop_handler(*_):\n    global STOP\n    STOP = True\n\ndef atomic_json(path, value):\n    tmp = path.with_suffix(path.suffix+\'.tmp\')\n    tmp.write_text(json.dumps(value, indent=2, allow_nan=False), encoding=\'utf-8\')\n    os.replace(tmp, path)\n\ndef atomic_save(path, value):\n    tmp = path.with_suffix(\'.tmp\')\n    with open(tmp, \'wb\') as file:\n        torch.save(value, file)\n        file.flush()\n        os.fsync(file.fileno())\n    os.replace(tmp, path)\n\ndef file_hash(path):\n    h = hashlib.sha256()\n    with open(path, \'rb\') as file:\n        for block in iter(lambda:file.read(8<<20), b\'\'):\n            h.update(block)\n    return h.hexdigest()\n\ndef state_hash(state):\n    h = hashlib.sha256()\n    for key, value in sorted(state.items()):\n        h.update(key.encode()); h.update(str(value.dtype).encode())\n        h.update(str(tuple(value.shape)).encode())\n        h.update(value.detach().cpu().contiguous().numpy().tobytes())\n    return h.hexdigest()\n\ndef cpu_state(model):\n    return {k:v.detach().cpu().clone() for k,v in model.state_dict().items()}\n\ndef load_resident(config):\n    """No hidden CPU fallback: train and validation stay on this worker\'s GPU."""\n    result = {}\n    required = sum(config[\'data\'][s][\'resident_fp32_bytes\'] for s in (\'train\',\'val\'))\n    free, total = torch.cuda.mem_get_info()\n    if free-required < config[\'reserve_gib\']*(1<<30):\n        raise RuntimeError(f\'GPU resident data need {required/(1<<30):.2f} GiB; \'\n                           f\'free={free/(1<<30):.2f}, reserve={config["reserve_gib"]} GiB. \'\n                           \'No CPU fallback. Reduce BOTH model micro batches in a NEW run, \'\n                           \'or use a documented new data-residency plan.\')\n    for split in (\'train\',\'val\'):\n        result[split] = {}\n        with h5py.File(config[\'data\'][split][\'path\'],\'r\') as h:\n            n = config[\'data\'][split][\'used_samples\']\n            for key in KEYS:\n                shape = (n,)+tuple(h[key].shape[1:])\n                target = torch.empty(shape, device=\'cuda\', dtype=torch.float32)\n                # Chunked staging avoids holding the entire H5 twice in CPU RAM.\n                for start in range(0,n,64):\n                    array = np.asarray(h[key][start:min(n,start+64)],dtype=np.float32)\n                    if not np.isfinite(array).all():\n                        raise ValueError(f\'{split}/{key}: nonfinite data\')\n                    target[start:start+len(array)].copy_(torch.from_numpy(array / 2047.))\n                result[split][key] = target\n    torch.cuda.synchronize()\n    return result\n\ndef validate(model, data, batch):\n    model.eval()\n    totals = torch.zeros(4,device=\'cuda\',dtype=torch.float64)\n    n = len(data[\'gt\'])\n    metric_rows=[]\n    from ssamrn.metrics import rr_metrics\n    with torch.inference_mode():\n        for start in range(0,n,batch):\n            b = {k:v[start:start+batch] for k,v in data.items()}\n            pred = model(b[\'pan\'],b[\'lms\'],b[\'ms\']).float()\n            if not torch.isfinite(pred).all():\n                raise RuntimeError(\'Nonfinite validation prediction\')\n            diff = (pred-b[\'gt\']).square()\n            totals[0] += F.mse_loss(pred,b[\'gt\'],reduction=\'sum\').double()\n            totals[1] += diff.numel()\n            totals[2] += (-10*diff.mean((2,3)).clamp_min(1e-30).log10()).mean(1).sum()\n            norms = pred.norm(dim=1)*b[\'gt\'].norm(dim=1)\n            valid = norms > 0\n            angles = torch.rad2deg(torch.acos(((pred*b[\'gt\']).sum(1)/norms.clamp_min(1e-30)).clamp(-1,1)))\n            counts = valid.sum((1,2))\n            if (counts==0).any():\n                raise RuntimeError(\'Validation sample has no valid SAM pixels\')\n            totals[3] += ((angles*valid).sum((1,2))/counts).sum()\n            cpu_pred=pred.cpu().numpy()*2047.; cpu_gt=b[\'gt\'].cpu().numpy()*2047.\n            for i in range(len(cpu_pred)):\n                metric_rows.append(rr_metrics(cpu_gt[i],cpu_pred[i]))\n    values = totals.cpu().tolist()\n    model.train()\n    return {\'mse\':values[0]/values[1], \'psnr\':values[2]/n, \'sam\':values[3]/n,\n            **{key.lower():float(np.mean([r[key] for r in metric_rows])) for key in (\'ERGAS\',\'SCC\',\'Q2n\')}}\n\ndef panels(arrays, pred, path, scene, protocol=\'RR full scene\'):\n    import matplotlib\n    matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    rgb_bands = [2,1,0]\n    ref = arrays[\'gt\'][rgb_bands].transpose(1,2,0)\n    low, high = np.percentile(ref,(1,99),axis=(0,1))\n    def rgb(a):\n        return np.clip((a[rgb_bands].transpose(1,2,0)-low)/np.maximum(high-low,1e-8),0,1)\n    fig,axes = plt.subplots(1,4,figsize=(16,4))\n    images = [rgb(arrays[\'ms\']),arrays[\'pan\'][0],rgb(pred),rgb(arrays[\'gt\'])]\n    for ax,title,image in zip(axes,(\'LR MS (nearest)\',\'PAN input\',\'Prediction\',\'GT\'),images):\n        ax.imshow(image, interpolation=\'nearest\', cmap=\'gray\' if image.ndim==2 else None)\n        ax.set_title(title); ax.axis(\'off\')\n    fig.suptitle(f\'{protocol} {scene} | same GT-derived MS contrast\')\n    fig.tight_layout(); fig.savefig(path,dpi=130); plt.close(fig)\n\ndef evaluate(config, folder, model, report):\n    import sys\n    sys.path.insert(0,str(Path(config[\'code_root\'])/\'SSA-MRN/src\'))\n    from ssamrn.metrics import rr_metrics, fr_metrics\n    eval_name=config.get(\'eval_checkpoint\',\'best\')\n    ck = torch.load(folder/(eval_name+\'.pt\'),map_location=\'cpu\',weights_only=False)\n    if ck[\'fingerprint\'] != config[\'fingerprint\']:\n        raise ValueError(\'Best fingerprint mismatch\')\n    evaluated_state=ck[\'model\']\n    if eval_name==\'latest\' and config[\'selected_beta\'] is not None:\n        evaluated_state=ck[\'ema_state\'][\'shadows\'][str(config[\'selected_beta\'])]\n    model.load_state_dict(evaluated_state); model.eval()\n    results = {\'best_epoch\':ck[\'epoch\'], \'best_val_mse\':ck.get(\'mse\',ck.get(\'best_mse\')), \'full_scene\':True,\n               \'test_precision\':\'FP32\', \'checkpoint_kind\':eval_name, \'limitations\':\'FR D_s/QNR MATLAB parity is unverified; RR Q2n/SCC parity is unverified.\',\n               \'splits\':{}}\n    inference_times=[]\n    for split in (\'RR\',\'FR\'):\n        rows=[]; tick=time.monotonic()\n        with h5py.File(config[\'data\'][split][\'path\'],\'r\') as h:\n            for index in range(len(h[\'pan\'])):\n                report(stage=\'evaluate_\'+split,scene=index+1,scenes=len(h[\'pan\']),\n                       train_eta_kst=None,total_eta_kst=None,eta_scope=\'test scoring/I/O unmeasured\')\n                keys = KEYS if split==\'RR\' else KEYS[:3]\n                arrays={k:np.asarray(h[k][index],dtype=np.float32) for k in keys}\n                inputs=[torch.from_numpy(arrays[k]/2047.).unsqueeze(0).cuda() for k in KEYS[:3]]\n                torch.cuda.synchronize(); infer_tick=time.monotonic()\n                with torch.inference_mode():\n                    gpu_pred=model(*inputs)[0].float()\n                torch.cuda.synchronize(); infer_seconds=time.monotonic()-infer_tick\n                inference_times.append({\'split\':split,\'scene_index\':index,\'seconds\':infer_seconds,\n                                        \'scope\':\'FP32 forward only; transfer/metrics excluded; no warmup exclusion\'})\n                pred=gpu_pred.cpu().numpy()*2047.\n                if not np.isfinite(pred).all():\n                    raise RuntimeError(\'Nonfinite test prediction\')\n                metrics=rr_metrics(arrays[\'gt\'],pred) if split==\'RR\' else fr_metrics(pred,arrays[\'lms\'],arrays[\'ms\'],arrays[\'pan\'])\n                if split==\'RR\':\n                    metrics[\'MSE_peak1\']=float(np.mean(((pred.astype(np.float64)-arrays[\'gt\'])/2047.)**2))\n                    if index in config[\'selection\'][\'indices\']:\n                        panels(arrays,pred,folder/f\'RR_scene_{index:03}.png\',index)\n                if not all(math.isfinite(float(v)) for v in metrics.values()):\n                    raise RuntimeError(\'Nonfinite test metric\')\n                rows.append({\'scene_index\':index, **metrics})\n                atomic_json(folder/f\'{split}_per_scene.json\',rows)\n                del inputs\n        results[\'splits\'][split]={\'count\':len(rows),\'seconds\':time.monotonic()-tick,\n                                 \'mean\':{k:float(np.mean([r[k] for r in rows])) for k in rows[0] if k!=\'scene_index\'}}\n    results[\'inference_times\']=inference_times\n    results[\'peak_gpu_gib\']=torch.cuda.max_memory_allocated()/(1<<30)\n    results[\'checkpoints\']={k:{\'sha256\':file_hash(folder/f\'{k}.pt\')} for k in (\'best\',\'latest\')}\n    atomic_json(folder/\'results.json\',results)\n    atomic_json(folder/\'evaluation_complete.json\',{\'RR\':results[\'splits\'][\'RR\'][\'count\'],\'FR\':results[\'splits\'][\'FR\'][\'count\'],\n                \'fingerprint\':config[\'fingerprint\'],\'best_sha256\':file_hash(folder/\'best.pt\'),\n                \'latest_sha256\':file_hash(folder/\'latest.pt\'),\'results_sha256\':file_hash(folder/\'results.json\')})\n\ndef train(config, label, physical_gpu):\n    import sys\n    sys.path.insert(0,str(Path(config[\'code_root\'])/\'SSA-MRN/src\'))\n    from ssamrn.models.ssa_mrn import RestoredPansharpeningNet\n    folder=Path(config[\'output\'])/label; folder.mkdir(exist_ok=True)\n    signal.signal(signal.SIGTERM,stop_handler); signal.signal(signal.SIGINT,stop_handler)\n    assert torch.cuda.device_count()==1, \'Each process must see exactly one GPU\'\n    torch.use_deterministic_algorithms(True)\n    torch.backends.cudnn.benchmark=False\n    torch.backends.cudnn.deterministic=True\n    torch.backends.cuda.matmul.allow_tf32=False\n    torch.backends.cudnn.allow_tf32=False\n    random.seed(config[\'seed\']); np.random.seed(config[\'seed\']); torch.manual_seed(config[\'seed\'])\n    torch.cuda.manual_seed_all(config[\'seed\'])\n    def report(**kw):\n        value={\'label\':label,\'physical_gpu\':physical_gpu,\'k\':4,\'total_epochs\':config[\'epochs\'],\n               \'updated_kst\':datetime.now(KST).isoformat(),\n               \'allocated_gib\':torch.cuda.memory_allocated()/(1<<30),\n               \'reserved_gib\':torch.cuda.memory_reserved()/(1<<30),\n               \'peak_gib\':torch.cuda.max_memory_allocated()/(1<<30),**kw}\n        atomic_json(folder/\'status.json\',value)\n        with open(folder/\'progress.jsonl\',\'a\',encoding=\'utf-8\') as file:\n            file.write(json.dumps(value,allow_nan=False)+\'\\n\')\n        print(json.dumps(value,ensure_ascii=False),flush=True)\n    report(stage=\'load_gpu_data\',train_eta_kst=None,total_eta_kst=None,eta_scope=\'measurement pending\')\n    data=load_resident(config) if config.get(\'job_type\')!=\'test\' else None\n    model=RestoredPansharpeningNet(channels=4,ssai_dimension=4).cuda()\n    initial=torch.load(Path(config[\'output\'])/\'initial.pt\',map_location=\'cpu\',weights_only=True)\n    model.load_state_dict(initial,strict=True)\n    initial_hash=state_hash(model.state_dict())\n    ema=EMA(model,config[\'betas\'])\n    candidate_best={}\n    candidate_payload={}\n    atomic_json(folder/\'initialization.json\',{\'state_sha256\':initial_hash,\'same_model\':\'RestoredPansharpeningNet\',\'k\':4})\n    opt=torch.optim.Adam(model.parameters(),lr=config[\'lr\'])\n    stepped=[False]\n    opt.register_step_post_hook(lambda *_:stepped.__setitem__(0,True))\n    scaler=torch.amp.GradScaler(\'cuda\',enabled=config[\'amp\'])\n    generator=torch.Generator(device=\'cuda\').manual_seed(config[\'seed\']+1000)\n    n=len(data[\'train\'][\'gt\']) if data is not None else 0; batch=config[\'batch\']; micro=config[\'micro\']\n    groups=math.ceil(n/batch)\n    epoch=0; position=0; order=None; order_hash=None; best=None; best_payload=None\n    history=[]; orders=[]; timings=[]\n    total=torch.zeros((),device=\'cuda\',dtype=torch.float64); count=0; skipped=0\n    spec_total=torch.zeros((),device=\'cuda\',dtype=torch.float64)\n    spec_count=torch.zeros((),device=\'cuda\',dtype=torch.float64)\n    objective_total=torch.zeros((),device=\'cuda\',dtype=torch.float64)\n    objective_samples=0\n    objective_weight=config[\'weight\']\n    # Save only at completed optimizer-step boundaries; no partial gradients.\n    active_train_seconds=0.; training_timer=None\n    def checkpoint():\n        nonlocal last_save, active_train_seconds, training_timer\n        if training_timer is not None:\n            torch.cuda.synchronize()\n            active_train_seconds+=time.monotonic()-training_timer\n            training_timer=time.monotonic()\n        rng={\'python\':random.getstate(),\'numpy\':np.random.get_state(),\'cpu\':torch.get_rng_state(),\n             \'cuda\':torch.cuda.get_rng_state(),\'generator\':generator.get_state()}\n        state={\'fingerprint\':config[\'fingerprint\'],\'config\':config[\'conditions\'],\n               \'model\':cpu_state(model),\'ema_state\':ema.state_dict(),\'candidate_best\':candidate_best,\'candidate_payload\':candidate_payload,\'optimizer\':opt.state_dict(),\'scaler\':scaler.state_dict(),\n               \'lr_schedule\':{\'type\':\'constant\',\'lr\':config[\'lr\']},\'rng\':rng,\n               \'epoch\':epoch,\'next_sample_position\':position,\'order\':None if order is None else order.cpu(),\n               \'order_hash\':order_hash,\'order_history\':orders,\'loss_sse\':total.cpu(),\'loss_elements\':count,\n               \'history\':history,\'timings\':timings,\'best_mse\':best,\'best_payload\':best_payload,\n               \'initial_state_sha256\':initial_hash,\'skipped_amp_steps\':skipped,\n               \'spec_total\':spec_total.cpu(),\'spec_count\':spec_count.cpu(),\n               \'objective_total\':objective_total.cpu(),\'objective_samples\':objective_samples,\'active_train_seconds\':active_train_seconds}\n        atomic_save(folder/\'latest.pt\',state)\n        # Preserve the actual historical best, even at non-improving epochs.\n        if best_payload is not None:\n            atomic_save(folder/\'best.pt\',best_payload)\n        for key,payload in candidate_payload.items():\n            atomic_save(folder/(\'best_beta_\'+key+\'.pt\'),payload)\n        atomic_json(folder/\'history.json\',history)\n        atomic_json(folder/\'orders.json\',orders)\n        last_save=time.monotonic()\n    if config.get(\'job_type\')==\'test\':\n        evaluate(config,folder,model,report); return\n    if (folder/\'latest.pt\').exists():\n        ck=torch.load(folder/\'latest.pt\',map_location=\'cpu\',weights_only=False)\n        if ck[\'fingerprint\']!=config[\'fingerprint\'] or ck[\'initial_state_sha256\']!=initial_hash:\n            raise ValueError(\'Resume conditions/initial state mismatch; use a new run\')\n        model.load_state_dict(ck[\'model\']); opt.load_state_dict(ck[\'optimizer\']); scaler.load_state_dict(ck[\'scaler\'])\n        ema.load_state_dict(ck[\'ema_state\'])\n        candidate_best=ck[\'candidate_best\'];candidate_payload=ck[\'candidate_payload\']\n        epoch=ck[\'epoch\']; position=ck[\'next_sample_position\']; order=ck[\'order\']\n        if order is not None: order=order.cuda()\n        order_hash=ck[\'order_hash\']; orders=ck[\'order_history\']; history=ck[\'history\']; timings=ck[\'timings\']\n        total=ck[\'loss_sse\'].cuda(); count=ck[\'loss_elements\']; best=ck[\'best_mse\']; best_payload=ck[\'best_payload\']\n        skipped=ck[\'skipped_amp_steps\']\n        spec_total=ck[\'spec_total\'].cuda(); spec_count=ck[\'spec_count\'].cuda()\n        objective_total=ck[\'objective_total\'].cuda(); objective_samples=ck[\'objective_samples\']; active_train_seconds=ck[\'active_train_seconds\']\n        r=ck[\'rng\']; random.setstate(r[\'python\']); np.random.set_state(r[\'numpy\'])\n        torch.set_rng_state(r[\'cpu\']); torch.cuda.set_rng_state(r[\'cuda\']); generator.set_state(r[\'generator\'])\n    last_save=time.monotonic(); checkpoint()\n    last_log=0.; model.train()\n    while epoch<config[\'epochs\']:\n        if STOP or time.time()>=config[\'deadline\']:\n            checkpoint(); report(stage=\'paused\',epoch=epoch,next_sample_position=position); return\n        tick=time.monotonic(); training_timer=tick; segment_start=position; steps_done=0\n        if order is None:\n            order=torch.randperm(n,device=\'cuda\',generator=generator)\n            order_hash=hashlib.sha256(order.cpu().numpy().tobytes()).hexdigest()\n            orders.append({\'epoch\':epoch+1,\'order_sha256\':order_hash})\n            atomic_json(folder/\'orders.json\',orders)\n            checkpoint()\n        for start in range(position,n,batch):\n            end=min(n,start+batch); opt.zero_grad(set_to_none=True)\n            group_ids=order[start:end]\n            group_valid=1 # unused: EMA changes no training loss\n            group_obj=torch.zeros((),device=\'cuda\',dtype=torch.float64)\n            for offset in range(start,end,micro):\n                ids=order[offset:min(end,offset+micro)]\n                b={k:v.index_select(0,ids) for k,v in data[\'train\'].items()}\n                with torch.autocast(\'cuda\',dtype=torch.float16,enabled=config[\'amp\']):\n                    pred=model(b[\'pan\'],b[\'lms\'],b[\'ms\'])\n                    loss=F.mse_loss(pred.float(),b[\'gt\'])\n                # Deliberately no per-batch .item()/CPU transfers.\n                total+=(pred.detach().float()-b[\'gt\']).square().sum(dtype=torch.float64)\n                count+=b[\'gt\'].numel()\n                spec_sum=torch.zeros((),device=\'cuda\');valid_count=torch.ones((),device=\'cuda\')\n                spec_total+=spec_sum.detach().double(); spec_count+=valid_count.double()\n                group_loss=loss*len(ids)/(end-start)\n                if objective_weight:\n                    group_loss=group_loss+objective_weight*spec_sum/group_valid\n                group_obj+=group_loss.detach().double()\n                scaler.scale(group_loss).backward()\n            objective_total+=group_obj*(end-start); objective_samples+=end-start\n            stepped[0]=False\n            scaler.step(opt); scaler.update()\n            skipped+=int(not stepped[0])\n            if stepped[0]: ema.update(model)\n            position=end; steps_done+=1\n            if time.monotonic()-last_save>=60:\n                checkpoint()\n            if STOP or time.time()>=config[\'deadline\'] or (config.get(\'stop_after_group\') and math.ceil(position/batch)>=config[\'stop_after_group\']):\n                checkpoint(); report(stage=\'paused\',epoch=epoch,next_sample_position=position); return\n            if time.monotonic()-last_log>=config[\'log_seconds\']:\n                torch.cuda.synchronize(); elapsed=time.monotonic()-tick\n                remaining_groups=math.ceil((n-position)/batch)\n                remainder=remaining_groups*elapsed/max(steps_done,1)\n                eta=None\n                if timings:\n                    remainder+=float(np.mean([t[\'validation_save_seconds\'] for t in timings]))\n                    remainder+=(config[\'epochs\']-epoch-1)*float(np.mean([t[\'epoch_wall_seconds\'] for t in timings]))\n                    eta=(datetime.now(KST)+timedelta(seconds=remainder)).isoformat()\n                mse=float(total.cpu())/max(count,1)\n                if not math.isfinite(mse): raise RuntimeError(\'Nonfinite train MSE\')\n                report(stage=\'train\',epoch=epoch+1,batch=math.ceil(position/batch),batches=groups,\n                       lr=opt.param_groups[0][\'lr\'],train_mse=mse,ema_updates=ema.updates,train_spectral=float(spec_total.cpu()/spec_count.clamp_min(1)),\n                       train_total=float(objective_total.cpu())/max(objective_samples,1),weight=objective_weight,elapsed_seconds=elapsed,\n                       train_eta_kst=eta,total_eta_kst=None,\n                       eta_scope=\'measured train+val+save; test scoring, figures and ZIP excluded\' if eta else \'first epoch measurement pending\')\n                last_log=time.monotonic()\n        torch.cuda.synchronize(); train_time=time.monotonic()-tick\n        active_train_seconds+=time.monotonic()-training_timer; training_timer=None\n        report(stage=\'validation\',epoch=epoch+1,train_eta_kst=None,total_eta_kst=None)\n        val_tick=time.monotonic(); online_val=validate(model,data[\'val\'],micro)\n        ema_values={}\n        online_state={k:v.detach().clone() for k,v in model.state_dict().items()}\n        for key,state in ema.shadows.items():\n            model.load_state_dict(state)\n            value=validate(model,data[\'val\'],micro);ema_values[key]=value\n            if key not in candidate_best or value[\'mse\']<candidate_best[key]:\n                candidate_best[key]=value[\'mse\']\n                candidate_payload[key]={\'fingerprint\':config[\'fingerprint\'],\'model\':cpu_state(model),\'epoch\':epoch+1,\n                    \'mse\':value[\'mse\'],\'validation\':value,\'config\':config[\'conditions\'],\'beta\':float(key),\'ema_updates\':ema.updates}\n        model.load_state_dict(online_state);del online_state\n        val=ema_values[str(config[\'selected_beta\'])] if config[\'selected_beta\'] is not None else online_val\n        torch.cuda.synchronize(); val_seconds=time.monotonic()-val_tick\n        mse=float(total.cpu())/count\n        if not math.isfinite(mse) or not all(math.isfinite(v) for v in val.values()):\n            raise RuntimeError(\'Nonfinite epoch statistics\')\n        row={\'epoch\':epoch+1,\'train_mse\':mse,\'val_mse\':val[\'mse\'],\'val_psnr\':val[\'psnr\'],\'val_sam\':val[\'sam\'],\n             \'skipped_amp_steps\':skipped,\'order_sha256\':order_hash,\'train_segment_seconds\':train_time,\n             \'validation_seconds\':val_seconds,\'resumed_mid_epoch\':segment_start>0,\n             \'train_spectral\':float(spec_total.cpu()/spec_count.clamp_min(1)),\n             \'train_total\':float(objective_total.cpu())/objective_samples,\'lambda\':objective_weight,\n             \'val_ergas\':val[\'ergas\'],\'val_scc\':val[\'scc\'],\'val_q2n\':val[\'q2n\']}\n        row.update(online_validation=online_val,ema_validation=ema_values,ema_updates=ema.updates)\n        for unused in (\'train_spectral\',\'train_total\',\'lambda\'):row.pop(unused,None)\n        history.append(row)\n        if best is None or val[\'mse\']<best:\n            best=val[\'mse\']; best_payload={\'fingerprint\':config[\'fingerprint\'],\'model\':({k:v.detach().cpu().clone() for k,v in ema.shadows[str(config[\'selected_beta\'])].items()} if config[\'selected_beta\'] is not None else cpu_state(model)),\n                                         \'epoch\':epoch+1,\'mse\':best,\'validation\':val,\'config\':config[\'conditions\']}\n        epoch+=1; position=0; order=None; order_hash=None; total.zero_(); count=0\n        spec_total.zero_(); spec_count.zero_(); objective_total.zero_(); objective_samples=0\n        save_tick=time.monotonic(); checkpoint(); save_seconds=time.monotonic()-save_tick\n        # Mid-epoch resumed segments are excluded from epoch-based ETA calibration.\n        if segment_start==0:\n            timings.append({\'epoch_wall_seconds\':time.monotonic()-tick,\n                            \'validation_save_seconds\':val_seconds+save_seconds})\n        atomic_json(folder/\'history.json\',history)\n        remaining=(config[\'epochs\']-epoch)*float(np.mean([t[\'epoch_wall_seconds\'] for t in timings])) if timings else None\n        report(stage=\'epoch_complete\',**row,train_eta_kst=(datetime.now(KST)+timedelta(seconds=remaining)).isoformat() if remaining is not None else None,\n               total_eta_kst=None,eta_scope=\'test scoring, figures and ZIP excluded\')\n    checkpoint()\n    atomic_json(folder/\'training_complete.json\',{\'epochs\':epoch,\'best_epoch\':best_payload[\'epoch\'],\'best_mse\':best})\n    # Free resident training arrays before full-scene FP32 evaluation.\n    del data, opt, scaler; torch.cuda.empty_cache()\n    atomic_json(folder/\'validation_result.json\',{\'best_epoch\':best_payload[\'epoch\'],\n                \'best_validation\':best_payload[\'validation\'],\'last_validation\':history[-1],\n                \'last_epoch\':epoch,\'peak_gpu_gib\':torch.cuda.max_memory_allocated()/(1<<30),\n                \'train_seconds_measured_segments\':sum(h[\'train_segment_seconds\'] for h in history),\n                \'train_active_seconds\':active_train_seconds,\n                \'timing_limit\':\'active train timer includes within-epoch checkpoint overhead; excludes data loading/validation; preserved across resume\'})\n    report(stage=\'training_complete_no_test\',epoch=epoch,train_eta_kst=datetime.now(KST).isoformat(),total_eta_kst=None)\n\ndef main():\n    parser=argparse.ArgumentParser(); parser.add_argument(\'--config\'); parser.add_argument(\'--label\'); parser.add_argument(\'--gpu\',type=int)\n    args=parser.parse_args(); config=json.loads(Path(args.config).read_text())\n    try:\n        train(config,args.label,args.gpu)\n    except Exception as exc:\n        folder=Path(config[\'output\'])/args.label; folder.mkdir(exist_ok=True)\n        atomic_json(folder/\'failure.json\',{\'error\':str(exc),\'type\':type(exc).__name__})\n        raise\n\nif __name__==\'__main__\':\n    main()\n', 'ema_core.py': 'import torch\nclass EMA:\n    """FP32 shadows, initialized exactly from online weights; update after each successful step.\n    Floating buffers are averaged, integer buffers copied. Shadows never feed back into Adam.\n    """\n    def __init__(self,model,betas):\n        assert len(set(betas))==len(betas) and all(0<b<1 for b in betas)\n        self.betas=list(betas);self.updates=0\n        self.shadows={str(b):{k:v.detach().clone() for k,v in model.state_dict().items()} for b in betas}\n    @torch.no_grad()\n    def update(self,model):\n        for key,state in self.shadows.items():\n            b=float(key)\n            for name,v in model.state_dict().items():\n                if v.is_floating_point():state[name].mul_(b).add_(v.detach(),alpha=1-b)\n                else:state[name].copy_(v)\n        self.updates+=1\n    def state_dict(self):\n        return {\'betas\':self.betas,\'updates\':self.updates,\'shadows\':{b:{k:v.detach().cpu().clone() for k,v in s.items()} for b,s in self.shadows.items()}}\n    def load_state_dict(self,value):\n        if value[\'betas\']!=self.betas:raise ValueError(\'EMA beta mismatch\')\n        if set(value[\'shadows\'])!=set(self.shadows):raise ValueError(\'EMA shadow mismatch\')\n        for b,s in self.shadows.items():\n            for k,v in s.items():v.copy_(value[\'shadows\'][b][k].to(v.device))\n        self.updates=value[\'updates\']\n', 'ema_preflight.py': "files={\n    'train':'QuickBird__Training_Dataset__train_qb.h5',\n    'val':'QuickBird__Training_Dataset__valid_qb.h5',\n    'RR':'QuickBird__Testing_Dataset_ReducedData_H5_Format__test_qb_multiExm1.h5',\n    'FR':'QuickBird__Testing_Dataset_FullData_H5_Format__test_qb_OrigScale_multiExm1.h5'}\ndata={}; scientific_data={}\ndashboard.refresh('4개 H5의 유한값·범위·SHA-256 검사 중 · 수분이 걸릴 수 있습니다')\nfor split,name in files.items():\n    dashboard.refresh(split+' 파일 검사 중 · 학습 시작 전 데이터 확인')\n    path=Path(DATA_ROOT)/name\n    if not path.is_file() or not h5py.is_hdf5(path):\n        raise FileNotFoundError(f'{path}: attach the private Dataset via Add Input; ignore ._ metadata files')\n    info={'file_name':name,'sha256':sha(path),'bytes':path.stat().st_size,'arrays':{}}\n    required=('pan','lms','ms','gt') if split!='FR' else ('pan','lms','ms')\n    with h5py.File(path,'r') as h:\n        if set(required)-set(h.keys()):\n            raise ValueError(f'{split}: missing keys {set(required)-set(h.keys())}; actual {list(h.keys())}')\n        shapes={k:tuple(h[k].shape) for k in required}\n        if any(len(s)!=4 for s in shapes.values()): raise ValueError(f'Expected NCHW: {shapes}')\n        n,c,height,width=shapes['lms']\n        if n<=0 or c!=4 or min(height,width)<4 or height%4 or width%4:\n            raise ValueError(f'QB 4 bands / x4 required: {shapes}')\n        if shapes['pan']!=(n,1,height,width) or shapes['ms']!=(n,4,height//4,width//4):\n            raise ValueError(f'Incompatible PAN/MS shapes: {shapes}')\n        if split!='FR' and shapes['gt']!=shapes['lms']: raise ValueError('GT shape mismatch')\n        if split in ('RR','FR') and (height%32 or width%32): raise ValueError('Q2n requires 32-aligned full scenes')\n        for key in required:\n            ds=h[key]; low=float('inf'); high=-float('inf')\n            if not np.issubdtype(ds.dtype,np.number): raise ValueError('Non-numeric H5 dtype')\n            per_sample=math.prod(ds.shape[1:])*max(ds.dtype.itemsize,4)\n            chunk=max(1,min(64,(64<<20)//per_sample))\n            for start in range(0,n,chunk):\n                array=np.asarray(ds[start:min(n,start+chunk)],dtype=np.float32)\n                if not np.isfinite(array).all(): raise ValueError(f'{split}/{key}: nonfinite values')\n                low=min(low,float(array.min())); high=max(high,float(array.max()))\n            info['arrays'][key]={'shape':list(ds.shape),'dtype':str(ds.dtype),'raw_min':low,'raw_max':high,\n                                  'normalized_min':low/2047.,'normalized_max':high/2047.,'all_finite':True}\n            # Allow tiny FP32-scale numerical excursions; preserve every original value.\n            # This is a validation tolerance in RAW DN units, not clipping/normalization.\n            range_tolerance_dn = 1e-4\n            info['arrays'][key]['range_tolerance_dn'] = range_tolerance_dn\n            info['arrays'][key]['tiny_range_excursion'] = bool(low<0 or high>2047)\n            # Supplied interpolated LMS can have real overshoot; its range is recorded.\n            if key in ('pan','ms','gt') and (low < -range_tolerance_dn or high > 2047+range_tolerance_dn or high<=1):\n                raise ValueError(f'{split}/{key}: unexpected QB raw DN range [{low},{high}]; verify normalization explicitly')\n        used=min(n,64 if split=='train' else 32) if MODE=='smoke' and split in ('train','val') else n\n        info['used_samples']=used\n        info['subset_rule']='first 64 train / first 32 val H5 indices' if MODE=='smoke' and split in ('train','val') else 'all samples'\n        info['resident_fp32_bytes']=sum(used*math.prod(shapes[k][1:])*4 for k in required) if split in ('train','val') else 0\n        if split=='FR': info['gt_policy']='No GT required, synthesized or used, even if an extra key exists'\n    scientific_data[split]=info\n    data[split]={'path':str(path),**info}\n    dashboard.data_checked(split,info)\nif len({v['sha256'] for v in scientific_data.values()})!=4:\n    raise ValueError('The four split files are not distinct by content')\nrr_count=scientific_data['RR']['arrays']['pan']['shape'][0]\nif rr_count<5: raise ValueError('At least 5 distinct RR scenes required')\nselection={'seed':SEED,'indices':np.random.default_rng(SEED).choice(rr_count,5,replace=False).tolist(),\n           'rule':'uniform without replacement before training/scoring','scene_id':'zero-based H5 sample index',\n           'full_scene':True,'display_order':['LR MS nearest','PAN','Prediction','GT'],\n           'contrast':'per-scene GT 1/99 percentiles; identical per-band contrast for LR MS, prediction, GT'}\n", 'spectral_loss.py': '"""Only the objective changes. FP32 normalized multispectral vectors, channel axis=1."""\nimport torch\nfrom torch.nn import functional as F\n\nEPS = 1e-4  # normalized QB vector norm; ~= 0.2047 raw DN norm\n\ndef spectral_components(prediction, target):\n    """Return summed 1-cosine and GT-only valid count over all N,H,W pixels.\n\n    GT norm <= EPS has no informative direction and is excluded, identically for\n    both arms. Prediction norm is NEVER used as a mask. A zero prediction against\n    valid GT therefore has penalty 1 and a finite, nonzero gradient. Norm floors\n    bound gradients; all arithmetic is FP32. No clipping of image values occurs.\n    """\n    pred=prediction.float(); gt=target.float()\n    valid=torch.linalg.vector_norm(gt,dim=1)>EPS\n    cosine=F.cosine_similarity(pred,gt,dim=1,eps=EPS).clamp(-1.,1.)\n    terms=(1.-cosine)*valid\n    return terms.sum(), valid.sum()\n\ndef spectral_mean(prediction,target):\n    total,count=spectral_components(prediction,target)\n    return total/count.clamp_min(1)\n\ndef training_group_backward(model, batch, optimizer, weight, micro):\n    """CPU/GPU test helper, same weighting as worker: exact effective-batch means."""\n    optimizer.zero_grad(set_to_none=True)\n    n=len(batch[\'gt\'])\n    valid=(torch.linalg.vector_norm(batch[\'gt\'].float(),dim=1)>EPS).sum().clamp_min(1)\n    for start in range(0,n,micro):\n        b={k:v[start:start+micro] for k,v in batch.items()}\n        pred=model(b[\'pan\'],b[\'lms\'],b[\'ms\'])\n        objective=F.mse_loss(pred,b[\'gt\'])*len(b[\'gt\'])/n\n        if weight:\n            total,_=spectral_components(pred,b[\'gt\'])\n            objective=objective+weight*total/valid\n        objective.backward()\n    optimizer.step()\n', 'ema_launcher_template.py': 'import os,sys,json,time,hashlib,shutil,subprocess,zipfile,signal,math,csv\nfrom pathlib import Path\nos.environ.setdefault(\'CUBLAS_WORKSPACE_CONFIG\',\':4096:8\')\nassert PHASE in (\'smoke\',\'probe\',\'select\',\'final_train\',\'final_test\')\nassert SEED in (42,43,44) and 0<MAX_SESSION_HOURS<=6\nassert RUN_TAG.startswith(\'EMA_1st_\') and all(c.isalnum() or c in \'_-\' for c in RUN_TAG)\noutput=Path(\'/kaggle/working\')/RUN_TAG\ndef sha(p):\n    h=hashlib.sha256()\n    with open(p,\'rb\') as f:\n        for b in iter(lambda:f.read(8<<20),b\'\'):h.update(b)\n    return h.hexdigest()\ndef digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True).encode()).hexdigest()\ndef write(p,x):\n    p.parent.mkdir(parents=True,exist_ok=True);tmp=p.with_suffix(p.suffix+\'.tmp\')\n    tmp.write_text(json.dumps(x,indent=2,allow_nan=False),encoding=\'utf-8\');os.replace(tmp,p)\ndef read(p):return json.loads(p.read_text(encoding=\'utf-8\'))\ndef verify(root):\n    e=read(root/\'experiment.json\')\n    if e[\'name\']!=\'EMA_1st\' or e[\'tag\']!=RUN_TAG:raise ValueError(\'Different experiment; nothing copied\')\n    m=read(root/\'artifact_manifest.json\')\n    for name,v in m.items():\n        p=root/name\n        if not p.resolve().is_relative_to(root.resolve()) or sha(p)!=v[\'sha256\']:raise ValueError(\'Archive evidence mismatch: \'+name)\n    return e\nif not output.exists() and PHASE!=\'smoke\':\n    if RESUME_FROM:\n        origin=Path(RESUME_FROM);verify(origin);shutil.copytree(origin,output)\n    else:\n        attached=list(Path(\'/kaggle/input\').rglob(SOURCE_ZIP)) if SOURCE_ZIP else []\n        if len(attached)==1:\n            temp=Path(\'/kaggle/working\')/(RUN_TAG+\'_restore_\'+str(time.time_ns()));temp.mkdir()\n            with zipfile.ZipFile(attached[0]) as z:\n                if z.testzip():raise ValueError(\'ZIP CRC error\')\n                for n in z.namelist():\n                    if not (temp/n).resolve().is_relative_to(temp.resolve()):raise ValueError(\'Unsafe ZIP path\')\n                z.extractall(temp)\n            roots=list(temp.rglob(\'experiment.json\'))\n            if len(roots)!=1:raise ValueError(\'Expected one experiment root\')\n            verify(roots[0].parent);shutil.copytree(roots[0].parent,output)\n        else:\n            roots=[p.parent for p in Path(\'/kaggle/input\').rglob(\'experiment.json\')\n                   if read(p).get(\'name\')==\'EMA_1st\' and read(p).get(\'tag\')==RUN_TAG]\n            if len(roots)!=1:raise ValueError(\'Set RESUME_FROM to exact attached folder containing experiment.json. Attach ONLY latest cumulative output.\')\n            verify(roots[0]);shutil.copytree(roots[0],output)\nif output.exists() and not (output/\'experiment.json\').exists():\n    raise FileExistsError(\'Existing directory is not a valid EMA experiment. Use a new RUN_TAG; nothing overwritten.\')\noutput.mkdir(parents=True,exist_ok=True)\nmissing=[p for m,p in [(\'numpy\',\'numpy\'),(\'h5py\',\'h5py\'),(\'scipy\',\'scipy\'),(\'skimage\',\'scikit-image\'),(\'matplotlib\',\'matplotlib\')] if __import__(\'importlib.util\',fromlist=[\'find_spec\']).find_spec(m) is None]\nif missing:subprocess.run([sys.executable,\'-m\',\'pip\',\'install\',*missing],check=True)\nimport numpy as np,h5py,torch\ncode=output/\'source\';code.mkdir(exist_ok=True)\nfor name,value in SOURCES.items():\n    p=code/name;p.parent.mkdir(parents=True,exist_ok=True)\n    if p.exists() and p.read_text(encoding=\'utf-8\')!=value:raise ValueError(\'Frozen source differs: \'+name)\n    p.write_text(value,encoding=\'utf-8\')\nsys.path.insert(0,str(code));sys.path.insert(0,str(code/\'SSA-MRN/src\'))\nfrom ema_dashboard import Dashboard\nfrom ema_worker import state_hash\nfrom ssamrn.models.ssa_mrn import RestoredPansharpeningNet\ndashboard=Dashboard(PHASE,output)\nTRAIN_SEED=SEED;SEED=42\nDATA_ROOT=\'/kaggle/input/datasets/biyonghiyon/ctrs-pan-sharpening-dataset\'\nMODE=\'smoke\' if PHASE==\'smoke\' else \'full\'\nexec(SOURCES[\'ema_preflight.py\'])\nSEED=TRAIN_SEED\nwrite(output/(\'data_manifest_\'+MODE+\'.json\'),scientific_data)\nenv={\'python\':sys.version,\'torch\':str(torch.__version__),\'numpy\':np.__version__,\'h5py\':h5py.__version__,\'cuda\':torch.version.cuda,\'cudnn\':torch.backends.cudnn.version(),\n     \'gpu\':[{\'index\':g,\'name\':torch.cuda.get_device_name(g),\'total_gib\':torch.cuda.get_device_properties(g).total_memory/(1<<30),\n             \'capability\':list(torch.cuda.get_device_capability(g))} for g in range(torch.cuda.device_count())]}\nif len(env[\'gpu\'])!=2 or env[\'gpu\'][0][\'name\']!=env[\'gpu\'][1][\'name\'] or env[\'gpu\'][0][\'total_gib\']!=env[\'gpu\'][1][\'total_gib\']:\n    raise RuntimeError(\'Require two matching GPUs; no silent fallback\')\nwrite(output/\'environment_current.json\',env)\ntry:(output/(\'nvidia_smi_\'+str(time.time_ns())+\'.txt\')).write_text(subprocess.check_output([\'nvidia-smi\'],text=True),encoding=\'utf-8\')\nexcept (OSError,subprocess.SubprocessError):pass\nraw={s:{\'sha256\':v[\'sha256\'],\'arrays\':{k:{\'shape\':a[\'shape\'],\'dtype\':a[\'dtype\']} for k,a in v[\'arrays\'].items()}} for s,v in scientific_data.items()}\nprotocol={\'name\':\'EMA_1st\',\'tag\':RUN_TAG,\'baseline_audit\':BASELINE_AUDIT,\'sources\':{k:hashlib.sha256(v.encode()).hexdigest() for k,v in SOURCES.items()},\n    \'data\':raw,\'k\':4,\'micro\':32,\'effective_batch\':32,\'epochs\':100,\'lr\':1e-4,\'optimizer\':\'Adam defaults\',\'precision\':\'FP32; AMP/TF32 off; deterministic\',\n    \'beta_candidates\':[0.99,0.999],\'beta_probe_epochs\':10,\'beta_selection\':\'lowest EMA validation MSE across 10 probe epochs; tie larger beta\',\n    \'ema_initialization\':\'exact initial online weights\',\'update\':\'after successful optimizer step from step1; constant beta; no warmup or feedback\',\n    \'checkpoint_selection\':\'each arm lowest validation MSE of its evaluated weights; ties earlier epoch\',\n    \'scene_indices\':selection[\'indices\'],\'seed_list\':[42,43,44],\n    \'environment\':{k:env[k] for k in (\'torch\',\'numpy\',\'h5py\',\'cuda\',\'cudnn\',\'gpu\')}}\nbasis=digest(protocol)\nif (output/\'experiment.json\').exists():\n    old=read(output/\'experiment.json\')\n    if old[\'basis\']!=basis:raise ValueError(\'Science/data/software/GPU conditions differ. Existing evidence preserved; start a new RUN_TAG.\')\nelse:write(output/\'experiment.json\',{**protocol,\'basis\':basis})\nwrite(output/\'selection_scenes.json\',selection)\ndeadline=time.time()+MAX_SESSION_HOURS*3600\nphasekey=PHASE+(\'_seed_\'+str(SEED) if PHASE.startswith(\'final_\') else \'\')\nstage=output/\'sessions\'/phasekey;stage.mkdir(parents=True,exist_ok=True)\ndef task(family,seed,label,gpu,betas,selected,epochs,job_type=\'train\',stop=0,reference=False):\n    folder=output/family/f\'seed_{seed}\';folder.mkdir(parents=True,exist_ok=True)\n    initial=folder/\'initial.pt\'\n    if not initial.exists():\n        if job_type==\'test\' or any(folder.rglob(\'latest.pt\')):raise ValueError(\'Saved initial state missing\')\n        torch.manual_seed(seed);m=RestoredPansharpeningNet(channels=4,ssai_dimension=4)\n        torch.save({k:v.detach().cpu().clone() for k,v in m.state_dict().items()},initial)\n        (folder/\'initial.sha256\').write_text(sha(initial));del m\n    if sha(initial)!=(folder/\'initial.sha256\').read_text():raise ValueError(\'Initial weights hash differs\')\n    sealhash=sha(output/\'final_settings.json\') if family==\'final\' else None\n    cond={\'basis\':basis,\'family\':family,\'seed\':seed,\'label\':label,\'epochs\':epochs,\'betas\':betas,\'selected_beta\':selected,\n          \'initial_sha256\':sha(initial),\'seal_sha256\':sealhash,\'samples\':{s:data[s][\'used_samples\'] for s in (\'train\',\'val\')}}\n    cfg={\'output\':str(folder),\'code_root\':str(code),\'conditions\':cond,\'fingerprint\':digest(cond),\'data\':data,\'selection\':selection,\'seed\':seed,\'epochs\':epochs,\n         \'batch\':32,\'micro\':32,\'amp\':False,\'lr\':1e-4,\'deadline\':deadline,\'reserve_gib\':4,\'log_seconds\':20,\'weight\':0.,\n         \'betas\':betas,\'selected_beta\':selected,\'job_type\':job_type,\'stop_after_group\':stop}\n    path=folder/(label+\'_config.json\')\n    if path.exists() and read(path)[\'fingerprint\']!=cfg[\'fingerprint\']:raise ValueError(\'Job config mismatch\')\n    write(path,cfg)\n    return {\'gpu\':gpu,\'label\':label,\'folder\':folder/label,\'config\':cfg,\'path\':path}\ndef run(jobs):\n    processes=[]\n    try:\n        for j in jobs:\n            j[\'folder\'].mkdir(exist_ok=True);dashboard.starting(j,0)\n            dashboard.rows[j[\'gpu\']][\'context\']=f"{PHASE} · β={j[\'config\'][\'selected_beta\']} · {j[\'folder\'].parent.name}"\n            log=open(j[\'folder\']/\'worker.log\',\'a\',encoding=\'utf-8\');environ=os.environ.copy();environ[\'CUDA_VISIBLE_DEVICES\']=str(j[\'gpu\'])\n            p=subprocess.Popen([sys.executable,str(code/\'ema_worker.py\'),\'--config\',str(j[\'path\']),\'--label\',j[\'label\'],\'--gpu\',str(j[\'gpu\'])],env=environ,stdout=log,stderr=log)\n            processes.append((p,j,log,time.monotonic()))\n        while any(p.poll() is None for p,_,_,_ in processes):\n            for p,j,_,_ in processes:\n                if (j[\'folder\']/\'status.json\').exists():dashboard.observe(j[\'gpu\'],read(j[\'folder\']/\'status.json\'))\n                if p.poll() not in (None,0):raise RuntimeError(\'Worker failed; see \'+str(j[\'folder\']/\'worker.log\'))\n            dashboard.refresh();time.sleep(5)\n        for p,j,log,tick in processes:\n            if p.returncode:raise RuntimeError(\'Worker failed; see \'+str(j[\'folder\']/\'worker.log\'))\n            write(j[\'folder\']/(\'session_\'+str(time.time_ns())+\'.json\'),{\'wall_seconds\':time.monotonic()-tick,\'job_type\':j[\'config\'][\'job_type\'],\'gpu\':j[\'gpu\']})\n            dashboard.finish(j,p.returncode)\n    finally:\n        for p,_,log,_ in processes:\n            if p.poll() is None:p.send_signal(signal.SIGINT)\n        wait_deadline=time.monotonic()+50\n        for p,_,log,_ in processes:\n            if p.poll() is None:\n                try:p.wait(timeout=max(.1,wait_deadline-time.monotonic()))\n                except subprocess.TimeoutExpired:p.terminate();p.wait()\n            log.close()\n        dashboard.refresh()\ndef pair_check(jobs):\n    paths=[j[\'folder\'] for j in jobs]\n    if read(paths[0]/\'initialization.json\')!=read(paths[1]/\'initialization.json\'):raise ValueError(\'Initialization differs\')\n    if read(paths[0]/\'orders.json\')!=read(paths[1]/\'orders.json\'):raise ValueError(\'Batch order differs\')\n    ck=[torch.load(p/\'latest.pt\',map_location=\'cpu\',weights_only=False) for p in paths]\n    if (ck[0][\'epoch\'],ck[0][\'next_sample_position\'])!=(ck[1][\'epoch\'],ck[1][\'next_sample_position\']):raise ValueError(\'Incomplete pair\')\n    exact=all(torch.equal(v,ck[1][\'model\'][k]) for k,v in ck[0][\'model\'].items())\n    write(paths[0].parent/\'pair_checks.json\',{\'initial_equal\':True,\'order_equal\':True,\'online_weights_exact_equal\':exact})\n    if not exact:raise ValueError(\'Online weights mismatch; investigate before interpreting EMA\')\ndef complete(jobs,test=False):return all((j[\'folder\']/(\'evaluation_complete.json\' if test else \'training_complete.json\')).exists() for j in jobs)\ndef curves():\n    import matplotlib;matplotlib.use(\'Agg\')\n    import matplotlib.pyplot as plt\n    for p in output.rglob(\'history.json\'):\n        h=read(p)\n        if not h:continue\n        fig,axes=plt.subplots(1,3,figsize=(12,3))\n        for ax,key in zip(axes,(\'train_mse\',\'val_mse\',\'val_sam\')):ax.plot([r[\'epoch\'] for r in h],[r[key] for r in h]);ax.set_title(key);ax.set_xlabel(\'epoch\')\n        fig.tight_layout();fig.savefig(p.parent/\'curves.png\',dpi=140);plt.close(fig)\ndef summarize():\n    rows=[];deltas=[]\n    for seed in (42,43,44):\n        root=output/\'final\'/f\'seed_{seed}\';files=[root/a/\'results.json\' for a in (\'baseline\',\'ema\')]\n        if not all(p.exists() for p in files):continue\n        rs=[read(p) for p in files]\n        for split in (\'RR\',\'FR\'):\n            for metric in rs[0][\'splits\'][split][\'mean\']:\n                a,b=[r[\'splits\'][split][\'mean\'][metric] for r in rs]\n                rows.append({\'seed\':seed,\'split\':split,\'metric\':metric,\'baseline\':a,\'ema\':b,\'ema_minus_baseline\':b-a})\n            scenes=[read(root/a/(split+\'_per_scene.json\')) for a in (\'baseline\',\'ema\')]\n            if [r[\'scene_index\'] for r in scenes[0]]!=[r[\'scene_index\'] for r in scenes[1]]:raise ValueError(\'Scene IDs differ\')\n            for a,b in zip(*scenes):deltas.append({\'seed\':seed,\'split\':split,\'scene_index\':a[\'scene_index\'],**{k:b[k]-a[k] for k in a if k!=\'scene_index\'}})\n    write(output/\'paired_scene_deltas.json\',deltas)\n    if rows:\n        with open(output/\'comparison.csv\',\'w\',newline=\'\',encoding=\'utf-8-sig\') as f:\n            w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)\n        groups={}\n        for r in rows:groups.setdefault((r[\'split\'],r[\'metric\']),[]).append(r)\n        statistics=[]\n        for (split,metric),values in groups.items():\n            item={\'split\':split,\'metric\':metric,\'n_seeds\':len(values)}\n            for k in (\'baseline\',\'ema\',\'ema_minus_baseline\'):\n                x=[r[k] for r in values];item[k+\'_mean\']=float(np.mean(x));item[k+\'_sample_std\']=float(np.std(x,ddof=1)) if len(x)>1 else None\n            statistics.append(item)\n        write(output/\'seed_statistics.json\',statistics)\ndef package(note):\n    curves();summarize();write(stage/\'status.json\',{\'note\':note,\'phase\':PHASE,\'seed\':SEED,\'remote_preservation_verified\':False})\n    inventory={p.relative_to(output).as_posix():{\'bytes\':p.stat().st_size,\'sha256\':sha(p)} for p in output.rglob(\'*\') if p.is_file() and p.name!=\'artifact_manifest.json\' and not p.name.endswith(\'.tmp\') and \'__pycache__\' not in p.parts}\n    write(output/\'artifact_manifest.json\',inventory)\n    archive=Path(\'/kaggle/working\')/(RUN_TAG+\'_\'+phasekey+\'_results.zip\');temp=archive.with_suffix(\'.tmp\')\n    with zipfile.ZipFile(temp,\'w\',zipfile.ZIP_DEFLATED,compresslevel=1) as z:\n        for name in list(inventory)+[\'artifact_manifest.json\']:z.write(output/name,RUN_TAG+\'/\'+name)\n    os.replace(temp,archive);print(note,\'\\nZIP:\',archive,\'\\nSHA-256:\',sha(archive),flush=True)\n    from IPython.display import display,FileLink\n    display(FileLink(str(archive)))\nnote=\'paused/failed; existing checkpoint evidence only\'\ntry:\n    if PHASE==\'smoke\':\n        jobs=[task(\'smoke\',42,\'baseline\',0,[],None,2,stop=1),task(\'smoke\',42,\'ema\',1,[0.99,0.999],0.999,2,stop=1)]\n        # Forced optimizer-boundary pause, then restore every EMA/RNG/optimizer state.\n        if not complete(jobs):run(jobs)\n        if time.time()<deadline:\n            for j in jobs:j[\'config\'][\'stop_after_group\']=0;write(j[\'path\'],j[\'config\'])\n            run(jobs)\n        if complete(jobs):\n            pair_check(jobs)\n            refs=[task(\'smoke_reference\',42,\'baseline\',0,[],None,2),task(\'smoke_reference\',42,\'ema\',1,[0.99,0.999],0.999,2)]\n            if not complete(refs):run(refs)\n            if complete(refs):\n                checks=[]\n                for a,b in zip(jobs,refs):\n                    ca=torch.load(a[\'folder\']/\'latest.pt\',map_location=\'cpu\',weights_only=False);cb=torch.load(b[\'folder\']/\'latest.pt\',map_location=\'cpu\',weights_only=False)\n                    checks.append({\'label\':a[\'label\'],\'online_equal\':state_hash(ca[\'model\'])==state_hash(cb[\'model\']),\n                         \'order_equal\':ca[\'order_history\']==cb[\'order_history\'],\'ema_update_count_equal\':ca[\'ema_state\'][\'updates\']==cb[\'ema_state\'][\'updates\'],\n                         \'ema_shadows_equal\':all(state_hash(s)==state_hash(cb[\'ema_state\'][\'shadows\'][k]) for k,s in ca[\'ema_state\'][\'shadows\'].items())})\n                passed=all(all(v for k,v in c.items() if k!=\'label\') for c in checks)\n                write(output/\'smoke_checks.json\',{\'passed\':passed,\'checks\':checks,\'excluded_from_final\':True})\n                if not passed:raise ValueError(\'Resume equivalence failed\')\n                note=\'Smoke passed; 2 epochs/64 train/32 validation only; not final performance\'\n    elif PHASE==\'probe\':\n        if not read(output/\'smoke_checks.json\')[\'passed\']:raise ValueError(\'Smoke must pass first\')\n        jobs=[task(\'probe\',42,\'baseline\',0,[],None,10),task(\'probe\',42,\'ema\',1,[0.99,0.999],0.999,10)]\n        run(jobs)\n        if complete(jobs):pair_check(jobs);note=\'10-epoch beta probe complete; no test used\'\n    elif PHASE==\'select\':\n        p=output/\'probe/seed_42/ema\';marker=p/\'training_complete.json\'\n        if not marker.exists() or read(marker)[\'epochs\']!=10:raise ValueError(\'Finish beta probe first\')\n        if not read(output/\'probe/seed_42/pair_checks.json\')[\'online_weights_exact_equal\']:raise ValueError(\'Pair checks missing\')\n        h=read(p/\'history.json\');scores={str(b):min(r[\'ema_validation\'][str(b)][\'mse\'] for r in h) for b in (0.99,0.999)}\n        beta=min((0.99,0.999),key=lambda b:(scores[str(b)],-b))\n        seal={\'basis\':basis,\'selected_beta\':beta,\'candidates\':[0.99,0.999],\'validation_scores\':scores,\'test_used\':False,\n              \'selection_scope\':\'10-epoch validation proxy; not proven optimum for 100 epochs\',\'evidence_sha256\':sha(p/\'history.json\')}\n        path=output/\'final_settings.json\'\n        if path.exists() and read(path)!=seal:raise ValueError(\'Selection already frozen; cannot change\')\n        write(path,seal);note=\'beta frozen from validation: \'+str(beta)\n    else:\n        seal=read(output/\'final_settings.json\')\n        if seal[\'basis\']!=basis or seal[\'test_used\'] or seal[\'evidence_sha256\']!=sha(output/\'probe/seed_42/ema/history.json\'):raise ValueError(\'Frozen selection evidence changed\')\n        beta=seal[\'selected_beta\'];test=PHASE==\'final_test\'\n        jobs=[task(\'final\',SEED,\'baseline\',0,[],None,100,\'test\' if test else \'train\'),task(\'final\',SEED,\'ema\',1,[beta],beta,100,\'test\' if test else \'train\')]\n        if test:\n            if not complete(jobs):raise ValueError(\'Finish both arms for this seed before test\')\n            pair_check(jobs)\n        run(jobs)\n        if complete(jobs,test):\n            if not test:pair_check(jobs)\n            note=phasekey+\' complete; \'+(\'one-seed result, not three-seed conclusion\' if SEED==42 else \'aggregate includes completed seeds only\')\nfinally:\n    package(note)\n', 'SSA-MRN/scripts/train.py': '"""Train the restored SSA-MRN using separate PanCollection train/validation H5 files."""\r\n\r\nimport argparse\r\nimport random\r\nimport sys\r\nfrom pathlib import Path\r\n\r\nimport numpy as np\r\nimport torch\r\nfrom torch.utils.data import DataLoader\r\n\r\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))\r\n\r\nfrom ssamrn.data.pancollection import PanCollectionH5\r\nfrom ssamrn.models.ssa_mrn import RestoredPansharpeningNet\r\n\r\nROOT = Path(__file__).resolve().parents[1]\r\n\r\n\r\ndef cpu_state(value):\r\n    """Save portable checkpoints from GPU backends, including DirectML."""\r\n    if isinstance(value, torch.Tensor):\r\n        return value.detach().cpu()\r\n    if isinstance(value, dict):\r\n        return {key: cpu_state(item) for key, item in value.items()}\r\n    if isinstance(value, (list, tuple)):\r\n        return type(value)(cpu_state(item) for item in value)\r\n    return value\r\n\r\n\r\ndef evaluate(model, loader, device):\r\n    model.eval()\r\n    total = 0.0\r\n    count = 0\r\n    with torch.no_grad():\r\n        for batch in loader:\r\n            pan, lms, ms, gt = (batch[key].to(device) for key in ("pan", "lms", "ms", "gt"))\r\n            prediction = model(pan, lms, ms)\r\n            total += torch.nn.functional.mse_loss(prediction, gt, reduction="sum").item()\r\n            count += gt.numel()\r\n    return total / count\r\n\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser()\r\n    parser.add_argument("--train", required=True, type=Path)\r\n    parser.add_argument("--val", required=True, type=Path)\r\n    parser.add_argument("--sensor", default="QB")\r\n    parser.add_argument("--epochs", type=int, default=100)\r\n    parser.add_argument("--batch-size", type=int, default=32)\r\n    parser.add_argument("--lr", type=float, default=1e-4)\r\n    parser.add_argument("--ssai-dimension", type=int, default=6,\r\n                        help="SSAI K (default: 6; use 4 for the upstream baseline)")\r\n    parser.add_argument("--seed", type=int, default=42, help="Working seed; paper seed unconfirmed")\r\n    parser.add_argument("--device", default="cpu", choices=("cpu", "mps", "cuda", "dml"))\r\n    parser.add_argument("--max-train-samples", type=int, default=None)\r\n    parser.add_argument("--max-val-samples", type=int, default=None)\r\n    parser.add_argument("--checkpoint-dir", type=Path,\r\n                        help="Defaults to an ignored local directory for this K and sensor")\r\n    parser.add_argument("--resume", type=Path)\r\n    args = parser.parse_args()\r\n    if args.train.resolve() == args.val.resolve():\r\n        parser.error("training and validation must use different H5 files")\r\n    if not args.train.is_file() or not args.val.is_file():\r\n        parser.error("both --train and --val must exist")\r\n    if args.epochs < 1 or args.batch_size < 1 or args.lr <= 0 or args.ssai_dimension < 1:\r\n        parser.error("epochs, batch-size, lr, and ssai-dimension must be positive")\r\n    if args.checkpoint_dir is None:\r\n        args.checkpoint_dir = (ROOT / "experiments/checkpoints/local"\r\n                               / f"k{args.ssai_dimension}" / f"{args.sensor.lower()}_full")\r\n    if args.device == "cuda" and not torch.cuda.is_available():\r\n        parser.error("CUDA is unavailable in this PyTorch environment")\r\n    if args.device == "dml":\r\n        try:\r\n            import torch_directml\r\n        except ImportError:\r\n            parser.error("Install torch-directml to use --device dml")\r\n        device = torch_directml.device()\r\n    else:\r\n        device = args.device\r\n\r\n    random.seed(args.seed)\r\n    np.random.seed(args.seed)\r\n    torch.manual_seed(args.seed)\r\n    train_set = PanCollectionH5(args.train, args.sensor, limit=args.max_train_samples)\r\n    val_set = PanCollectionH5(args.val, args.sensor, limit=args.max_val_samples)\r\n    if train_set.channels != val_set.channels:\r\n        parser.error("training and validation channel counts differ")\r\n    train_loader = DataLoader(train_set, batch_size=args.batch_size, shuffle=True, num_workers=0)\r\n    val_loader = DataLoader(val_set, batch_size=args.batch_size, shuffle=False, num_workers=0)\r\n\r\n    model = RestoredPansharpeningNet(\r\n        channels=train_set.channels, ssai_dimension=args.ssai_dimension\r\n    )\r\n    if args.device == "dml":\r\n        model.use_directml_prelu()\r\n    model = model.to(device)\r\n    optimizer = torch.optim.Adam(model.parameters(), lr=args.lr)\r\n    start_epoch = 0\r\n    if args.resume:\r\n        checkpoint = torch.load(args.resume, map_location="cpu", weights_only=True)\r\n        if checkpoint["sensor"] != args.sensor.upper() or checkpoint["channels"] != train_set.channels:\r\n            parser.error("checkpoint sensor/channels do not match the dataset")\r\n        if checkpoint.get("ssai_dimension", 4) != args.ssai_dimension:\r\n            parser.error("checkpoint SSAI dimension does not match --ssai-dimension")\r\n        if checkpoint.get("learning_rate", args.lr) != args.lr or checkpoint.get("batch_size", args.batch_size) != args.batch_size:\r\n            parser.error("checkpoint learning rate/batch size do not match this run")\r\n        model.load_state_dict(checkpoint["model"])\r\n        optimizer.load_state_dict(checkpoint["optimizer"])\r\n        start_epoch = checkpoint["epoch"]\r\n        if "torch_rng_state" in checkpoint:\r\n            torch.set_rng_state(checkpoint["torch_rng_state"])\r\n\r\n    args.checkpoint_dir.mkdir(parents=True, exist_ok=True)\r\n    for epoch in range(start_epoch, args.epochs):\r\n        model.train()\r\n        losses = []\r\n        for batch in train_loader:\r\n            pan, lms, ms, gt = (batch[key].to(device) for key in ("pan", "lms", "ms", "gt"))\r\n            optimizer.zero_grad(set_to_none=True)\r\n            loss = torch.nn.functional.mse_loss(model(pan, lms, ms), gt)\r\n            loss.backward()\r\n            optimizer.step()\r\n            losses.append(loss.item())\r\n        val_mse = evaluate(model, val_loader, device)\r\n        print(f"epoch={epoch + 1} train_mse={np.mean(losses):.8f} val_mse={val_mse:.8f}", flush=True)\r\n        checkpoint = {"epoch": epoch + 1, "sensor": args.sensor.upper(),\r\n                      "channels": train_set.channels, "model": cpu_state(model.state_dict()),\r\n                      "optimizer": cpu_state(optimizer.state_dict()), "seed": args.seed,\r\n                      "ssai_dimension": args.ssai_dimension, "learning_rate": args.lr,\r\n                      "batch_size": args.batch_size,\r\n                      "torch_rng_state": torch.get_rng_state()}\r\n        torch.save(checkpoint, args.checkpoint_dir / "latest.pt")\r\n\r\n\r\nif __name__ == "__main__":\r\n    main()\r\n', 'SSA-MRN/scripts/train_controlled.py': '"""Controlled CUDA training; isolated RNG, best/latest and epoch-boundary resume."""\nimport os\nos.environ.setdefault("CUBLAS_WORKSPACE_CONFIG", ":4096:8")\nimport argparse, json, math, time, sys\nfrom pathlib import Path\nimport torch\nimport torch.nn.functional as F\nfrom torch.utils.data import DataLoader\nsys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))\nfrom ssamrn.data.pancollection import PanCollectionH5\nfrom ssamrn.models.ssa_mrn import RestoredPansharpeningNet\nfrom ssamrn.observation import load_profile\nfrom train import cpu_state, evaluate\n\ndef atomic_save(value, path):\n    tmp = path.with_suffix(".tmp")\n    torch.save(value, tmp); os.replace(tmp, path)\n\nclass IndexedPanCollectionH5(PanCollectionH5):\n    def __getitem__(self, index):\n        sample = super().__getitem__(index)\n        sample["index"] = index\n        return sample\n\n\ndef auxiliary(pred, gt, ms, kind, operator=None, margin=0, phases=None):\n    if kind == "spectral":\n        return (1-F.cosine_similarity(pred, gt, dim=1, eps=1e-8)).mean()\n    if kind == "edge":\n        return ((pred[...,1:,:]-pred[...,:-1,:])-(gt[...,1:,:]-gt[...,:-1,:])).square().mean() + ((pred[...,1:]-pred[...,:-1])-(gt[...,1:]-gt[...,:-1])).square().mean()\n    if kind == "consistency":\n        if operator is None or phases is None:\n            raise ValueError("Consistency requires an audited observation operator and fixed phases")\n        return operator.loss(pred, ms, margin, phases)\n    return pred.new_zeros(())\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("--config",type=Path,required=True); p.add_argument("--output",type=Path,required=True); p.add_argument("--resume",choices=["latest","best"])\n    p.add_argument("--extend-epochs",action="store_true",help="Allow only a larger epoch target when resuming a screened candidate")\n    p.add_argument("--stop-after-epoch",type=int,help="Verification only; stop after saving the named epoch")\n    a=p.parse_args(); c=json.loads(a.config.read_text()); a.output.mkdir(parents=True,exist_ok=True)\n    if not torch.cuda.is_available(): raise RuntimeError("CUDA required")\n    torch.use_deterministic_algorithms(True); torch.backends.cudnn.benchmark=False\n    torch.manual_seed(c["seed"]); torch.cuda.manual_seed_all(c["seed"])\n    gen=torch.Generator().manual_seed(c["seed"])\n    tr=IndexedPanCollectionH5(Path(c["train"]),c["sensor"],limit=c.get("limit")); va=PanCollectionH5(Path(c["val"]),c["sensor"],limit=c.get("limit"))\n    if Path(c["train"]).resolve()==Path(c["val"]).resolve(): raise ValueError("train/val overlap")\n    if tr.channels != va.channels: raise ValueError("channels mismatch")\n    loader=DataLoader(tr,batch_size=c["batch_size"],shuffle=True,generator=gen,num_workers=0)\n    validation=DataLoader(va,batch_size=c["micro_batch"],shuffle=False,num_workers=0)\n    operator, profile, phase_table = None, None, None\n    if c["loss"] == "consistency":\n        observation = c.get("observation")\n        if not observation or not observation.get("sha256"):\n            raise ValueError("Audited observation profile and hash required")\n        path = Path(observation["profile"])\n        if not path.is_absolute(): path = Path(__file__).resolve().parents[1] / path\n        operator, profile = load_profile(path, observation["sha256"], c["sensor"], c["train"])\n        operator = operator.float().cuda()\n        phase_table = torch.tensor(profile["phases"], dtype=torch.long)\n    model=RestoredPansharpeningNet(channels=tr.channels,ssai_dimension=c["k"]).cuda()\n    opt=torch.optim.Adam(model.parameters(),lr=c["lr"]); start=0; best=float("inf")\n    if a.resume:\n        ck=torch.load(a.output/(a.resume+".pt"),map_location="cpu",weights_only=True)\n        if ck["config"]!=c:\n            old=ck["config"]\n            if not (a.extend_epochs and c["epochs"]>old["epochs"] and {k:v for k,v in old.items() if k!="epochs"}=={k:v for k,v in c.items() if k!="epochs"}):\n                raise ValueError("resume config mismatch")\n        model.load_state_dict(ck["model"]); opt.load_state_dict(ck["optimizer"])\n        torch.set_rng_state(ck["rng"]); torch.cuda.set_rng_state_all(ck["cuda_rng"]); gen.set_state(ck["loader_rng"])\n        start=ck["epoch"]; best=ck["best_mse"]\n    for epoch in range(start,c["epochs"]):\n        model.train(); total=0.; count=0; tick=time.time()\n        for batch_index,b in enumerate(loader):\n            opt.zero_grad(set_to_none=True); n=len(b["gt"])\n            for offset in range(0,n,c["micro_batch"]):\n                pan,lms,ms,gt=(b[key][offset:offset+c["micro_batch"]].cuda() for key in ["pan","lms","ms","gt"])\n                pred=model(pan,lms,ms); mse=F.mse_loss(pred,gt)\n                phases = phase_table[b["index"][offset:offset+c["micro_batch"]]] if phase_table is not None else None\n                loss=mse+c["weight"]*auxiliary(pred,gt,ms,c["loss"],operator,profile["lr_margin"] if profile else 0,phases)\n                if not torch.isfinite(loss): raise RuntimeError("nonfinite loss")\n                (loss*len(gt)/n).backward(); total+=mse.item()*len(gt); count+=len(gt)\n            opt.step()\n            if batch_index % 50 == 0:\n                print(json.dumps(dict(epoch=epoch+1,batch=batch_index+1,batches=len(loader),train_mse=total/count)),flush=True)\n        val=evaluate(model,validation,"cuda")\n        if not math.isfinite(val): raise RuntimeError("nonfinite validation")\n        improved=val<best; best=min(best,val)\n        row=dict(epoch=epoch+1,train_mse=total/count,val_mse=val,seconds=time.time()-tick)\n        print(json.dumps(row),flush=True)\n        # Resume can replay an incomplete epoch; keep one record per completed epoch.\n        history=a.output/"history.jsonl"\n        rows=[json.loads(x) for x in history.read_text().splitlines()] if history.exists() else []\n        rows=[x for x in rows if x["epoch"]<epoch+1]+[row]\n        tmp=history.with_suffix(".tmp"); tmp.write_text("".join(json.dumps(x)+"\\n" for x in rows)); os.replace(tmp,history)\n        ck=dict(config=c,epoch=epoch+1,best_mse=best,model=cpu_state(model.state_dict()),optimizer=cpu_state(opt.state_dict()),rng=torch.get_rng_state(),cuda_rng=torch.cuda.get_rng_state_all(),loader_rng=gen.get_state())\n        atomic_save(ck,a.output/"latest.pt")\n        if improved: atomic_save(ck,a.output/"best.pt")\n        if a.stop_after_epoch and epoch+1>=a.stop_after_epoch: return\n    (a.output/"complete.json").write_text(json.dumps(dict(config=c,best_mse=best,epoch=c["epochs"]),indent=2))\nif __name__=="__main__": main()\n', 'SSA-MRN/src/ssamrn/metrics.py': '"""PanCollection RR/FR metrics, following DLPan-Toolbox definitions.\r\n\r\nFR PAN resizing uses scikit-image\'s antialiased bicubic approximation to\r\nMATLAB imresize; D_s/QNR must be parity-checked before a strict paper claim.\r\n"""\r\n\r\nimport numpy as np\r\nfrom scipy.ndimage import convolve, convolve1d\r\nfrom skimage.transform import resize\r\n\r\n\r\ndef _chw(image):\r\n    array = np.asarray(image, dtype=np.float64)\r\n    if array.ndim != 3 or not np.isfinite(array).all():\r\n        raise ValueError("Expected finite CHW image")\r\n    return array\r\n\r\n\r\ndef _onion(a, b):\r\n    """Cayley-Dickson multiplication used by MATLAB onions_quality."""\r\n    n = a.shape[-1]\r\n    if n == 1:\r\n        return a * b\r\n    half = n // 2\r\n    x, y = a[..., :half], a[..., half:]\r\n    z, w = b[..., :half], b[..., half:]\r\n    cy = np.concatenate((y[..., :1], -y[..., 1:]), axis=-1)\r\n    cw = np.concatenate((w[..., :1], -w[..., 1:]), axis=-1)\r\n    if n == 2:\r\n        return np.concatenate((x * z - w * y, x * w + z * y), axis=-1)\r\n    cx = np.concatenate((x[..., :1], -x[..., 1:]), axis=-1)\r\n    return np.concatenate((_onion(x, z) - _onion(w, cy), _onion(cx, w) + _onion(z, y)), axis=-1)\r\n\r\n\r\ndef q2n(reference, fused, block=32):\r\n    """Q4/Q8 with nonoverlapping 32-pixel blocks, matching q2n.m here."""\r\n    reference, fused = _chw(reference), _chw(fused)\r\n    if reference.shape != fused.shape:\r\n        raise ValueError("Q2n shapes differ")\r\n    channels, height, width = reference.shape\r\n    if height % block or width % block or channels & (channels - 1):\r\n        raise ValueError("Q2n requires block-aligned images and power-of-2 bands")\r\n    def blocks(image):\r\n        # MATLAB uint16 saturates/rounds values before the hypercomplex index.\r\n        image = np.rint(np.clip(image, 0, 65535)).transpose(1, 2, 0)\r\n        return image.reshape(height // block, block, width // block, block, channels).transpose(0, 2, 1, 3, 4).reshape(-1, block, block, channels)\r\n    a, b = blocks(reference), blocks(fused)\r\n    mean_a = a.mean(axis=(1, 2), keepdims=True)\r\n    std_a = a.std(axis=(1, 2), ddof=1, keepdims=True)\r\n    std_a = np.where(std_a == 0, np.finfo(float).eps, std_a)\r\n    a = (a - mean_a) / std_a + 1\r\n    b = (b - mean_a) / std_a + 1\r\n    b[..., 1:] *= -1\r\n    m1, m2 = a.mean(axis=(1, 2)), b.mean(axis=(1, 2))\r\n    m1_sq, m2_sq = np.sum(m1 * m1, axis=-1), np.sum(m2 * m2, axis=-1)\r\n    bias = np.divide(2 * np.sqrt(m1_sq * m2_sq), m1_sq + m2_sq,\r\n                     out=np.zeros_like(m1_sq), where=(m1_sq + m2_sq) != 0)\r\n    n = block * block\r\n    variance_term = n / (n - 1) * (\r\n        np.mean(np.sum(a * a + b * b, axis=-1), axis=(1, 2)) - m1_sq - m2_sq\r\n    )\r\n    quality = np.empty((len(a), channels), dtype=np.float64)\r\n    nonzero = np.abs(variance_term) > 1e-12\r\n    quality[~nonzero] = 0\r\n    quality[~nonzero, -1] = bias[~nonzero]\r\n    if np.any(nonzero):\r\n        product_mean = _onion(a[nonzero], b[nonzero]).mean(axis=(1, 2))\r\n        mean_product = _onion(m1[nonzero], m2[nonzero])\r\n        quality[nonzero] = (product_mean - mean_product) * (n / (n - 1) * bias[nonzero] * 2 / variance_term[nonzero])[:, None]\r\n    return float(np.linalg.norm(quality, axis=-1).mean())\r\n\r\n\r\ndef rr_metrics(reference, fused, *, ratio=4):\r\n    """Return per-image RR metrics, not an image-concatenated score."""\r\n    reference, fused = _chw(reference), _chw(fused)\r\n    if reference.shape != fused.shape:\r\n        raise ValueError("RR shapes differ")\r\n    diff = fused - reference\r\n    dot = np.sum(reference * fused, axis=0)\r\n    norms = np.linalg.norm(reference, axis=0) * np.linalg.norm(fused, axis=0)\r\n    valid = norms > 0\r\n    sam = float(np.degrees(np.arccos(np.clip(dot[valid] / norms[valid], -1, 1))).mean())\r\n    means = reference.mean(axis=(1, 2))\r\n    band_mse = np.mean(diff * diff, axis=(1, 2))\r\n    ergas = float(100 / ratio * np.sqrt(np.mean(band_mse / np.maximum(means * means, 1e-30))))\r\n    # MATLAB SCC: Sobel gradient magnitudes on a 1-pixel cropped image.\r\n    sobel = np.array([[1, 2, 1], [0, 0, 0], [-1, -2, -1]], dtype=float)\r\n    def gradients(image):\r\n        image = image[:, 1:-1, 1:-1]\r\n        gy = np.stack([convolve(band, sobel, mode="constant") for band in image])\r\n        gx = np.stack([convolve(band, sobel.T, mode="constant") for band in image])\r\n        return np.hypot(gx, gy)\r\n    a, b = gradients(reference), gradients(fused)\r\n    scc = float(np.sum(a * b) / np.sqrt(np.sum(a * a) * np.sum(b * b)))\r\n    # The paper does not specify its PSNR convention. Use the empirically\r\n    # closest documented choice: per-band PSNR at peak 2047, then average.\r\n    psnr = float(np.mean(10 * np.log10(2047 * 2047 / np.maximum(band_mse, 1e-30))))\r\n    return {"SAM": sam, "ERGAS": ergas, "PSNR": psnr,\r\n            "SCC": scc, "Q2n": q2n(reference, fused)}\r\n\r\n\r\ndef _block_uqi(a, b, block=32):\r\n    """Average MATLAB uqi over nonoverlapping blocks."""\r\n    height, width = a.shape\r\n    if a.shape != b.shape or height % block or width % block:\r\n        raise ValueError("UQI shapes are not block aligned")\r\n    def group(image):\r\n        return image.reshape(height // block, block, width // block, block).transpose(0, 2, 1, 3).reshape(-1, block * block)\r\n    x, y = group(a), group(b)\r\n    mx, my = x.mean(axis=1), y.mean(axis=1)\r\n    vx, vy = x.var(axis=1, ddof=1), y.var(axis=1, ddof=1)\r\n    cov = np.sum((x - mx[:, None]) * (y - my[:, None]), axis=1) / (x.shape[1] - 1)\r\n    denominator = (vx + vy) * (mx * mx + my * my)\r\n    quality = np.divide(4 * cov * mx * my, denominator,\r\n                        out=np.zeros_like(mx), where=np.abs(denominator) > 1e-30)\r\n    return float(quality.mean())\r\n\r\n\r\ndef _interp23tap(image, ratio=4):\r\n    coeff = 2 * np.array([.5, .305334091185, 0, -.072698593239, 0, .021809577942,\r\n                          0, -.005192756653, 0, .000807762146, 0, -.000060081482])\r\n    coeff = np.r_[coeff[:0:-1], coeff]\r\n    for stage in range(int(np.log2(ratio))):\r\n        up = np.zeros((image.shape[0] * 2, image.shape[1] * 2))\r\n        offset = 1 if stage == 0 else 0\r\n        up[offset::2, offset::2] = image\r\n        image = convolve1d(convolve1d(up, coeff, axis=0, mode="wrap"), coeff, axis=1, mode="wrap")\r\n    return image\r\n\r\n\r\ndef fr_metrics(fused, lms, ms, pan, *, ratio=4, block=32):\r\n    """Toolbox-style QNR; PAN antialias resize is not MATLAB-bit-exact."""\r\n    fused, lms, ms = _chw(fused), _chw(lms), _chw(ms)\r\n    pan = np.asarray(pan, dtype=np.float64).squeeze()\r\n    if fused.shape != lms.shape or pan.shape != fused.shape[1:] or ms.shape[1:] != (pan.shape[0] // ratio, pan.shape[1] // ratio):\r\n        raise ValueError("FR input shapes differ")\r\n    channels = fused.shape[0]\r\n    spectral = [abs(_block_uqi(fused[i], fused[j], block) - _block_uqi(lms[i], lms[j], block))\r\n                for i in range(channels) for j in range(i + 1, channels)]\r\n    down = resize(pan, ms.shape[1:], order=3, mode="reflect", anti_aliasing=True, preserve_range=True)\r\n    pan_filtered = _interp23tap(down, ratio)\r\n    spatial = [abs(_block_uqi(fused[i], pan, block) - _block_uqi(lms[i], pan_filtered, block))\r\n               for i in range(channels)]\r\n    d_lambda, d_s = float(np.mean(spectral)), float(np.mean(spatial))\r\n    return {"D_lambda": d_lambda, "D_s": d_s, "QNR": (1 - d_lambda) * (1 - d_s)}\r\n', 'SSA-MRN/src/ssamrn/models/ssa_mrn.py': '"""Minimal forward-path repair around the untouched official network.py.\r\n\r\nThe official forward(pan, lms) references an undefined `ms`. Its three\r\nspatial stages require PAN and interpolated LMS at full resolution, plus\r\nthe original MS at one-quarter resolution. This adapter supplies that input\r\nexplicitly and retains the original modules, parameter names and operations.\r\n"""\r\n\r\nimport importlib.util\r\nfrom pathlib import Path\r\n\r\nimport torch\r\nfrom torch import nn\r\n\r\n\r\nUPSTREAM_PATH = Path(__file__).resolve().parents[3] / "references/upstream/network.py"\r\n\r\n\r\ndef _upstream_model():\r\n    if not UPSTREAM_PATH.is_file():\r\n        raise FileNotFoundError(f"Initialize the official SSA-MRN submodule: {UPSTREAM_PATH}")\r\n    spec = importlib.util.spec_from_file_location("ssamrn_official_network", UPSTREAM_PATH)\r\n    module = importlib.util.module_from_spec(spec)\r\n    spec.loader.exec_module(module)\r\n    return module.PansharpeningNet\r\n\r\n\r\nclass DirectMLPReLU(nn.PReLU):\r\n    """Equivalent PReLU expression avoiding a DirectML batch backward error."""\r\n\r\n    def forward(self, input):\r\n        slope = self.weight.view(1, -1, 1, 1)\r\n        return torch.where(input > 0, input, slope * input)\r\n\r\n\r\nclass RestoredPansharpeningNet(_upstream_model()):\r\n    """Official layers with an explicit low-resolution MS input."""\r\n\r\n    def __init__(self, channels, ssai_dimension=4, guide_channels=1):\r\n        super().__init__(channels)\r\n        if guide_channels not in (1, 3):\r\n            raise ValueError("guide_channels must be 1 (PAN) or 3 (RGB)")\r\n        self.guide_channels = guide_channels\r\n        if guide_channels == 3:\r\n            self.conv1t1 = nn.Conv2d(3, 3, 3, padding=1)\r\n            self.cov2t64 = nn.Conv2d(channels + 6, 64, 3, padding=1)\r\n            for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\r\n                for block in blocks:\r\n                    block.conv1t6 = nn.Conv2d(3, 4, 3, padding=1)\r\n        if ssai_dimension < 1:\r\n            raise ValueError("ssai_dimension must be positive")\r\n        self.ssai_dimension = ssai_dimension\r\n        if ssai_dimension == 4:\r\n            return  # Preserve the published upstream architecture and existing checkpoints.\r\n\r\n        # The upstream code hard-codes K=4, while the paper specifies K=6.\r\n        # Resize only the layers used by the restored forward path; leave upstream untouched.\r\n        self.fixed = ssai_dimension\r\n        for blocks in (self.SSA_blocks, self.SSA_blocks1, self.SSA_blocks2):\r\n            for block in blocks:\r\n                block.fixed = ssai_dimension\r\n                block.conv1t6 = nn.Conv2d(guide_channels, ssai_dimension, 3, padding=1)\r\n                block.conv6t6 = nn.Conv2d(ssai_dimension, ssai_dimension, 3, padding=1)\r\n                block.conv7t6_3 = nn.Conv2d(channels + 1, ssai_dimension, 3, padding=1)\r\n        for name in ("conv48tnum1", "conv48tnum2", "conv48tnum3"):\r\n            setattr(self, name, nn.Conv2d(ssai_dimension * channels, channels, 3, padding=1))\r\n\r\n    def use_directml_prelu(self):\r\n        """Keep PReLU weights/checkpoints while using a DirectML-safe backward."""\r\n        for name, module in self.named_modules():\r\n            if not name or not isinstance(module, nn.PReLU):\r\n                continue\r\n            parent = self.get_submodule(name.rpartition(".")[0]) if "." in name else self\r\n            replacement = DirectMLPReLU(module.num_parameters)\r\n            with torch.no_grad():\r\n                replacement.weight.copy_(module.weight)\r\n            setattr(parent, name.rpartition(".")[2], replacement)\r\n\r\n    def _attend(self, pan, features, ms, blocks, fusion, activation):\r\n        outputs = []\r\n        for band in range(self.channels):\r\n            band_input = torch.cat([features, ms[:, band : band + 1]], dim=1)\r\n            outputs.append(blocks[band](pan, band_input))\r\n        return activation(fusion(torch.cat(outputs, dim=1)))\r\n\r\n    def forward(self, pan, lms, ms):\r\n        if pan.ndim != 4 or lms.ndim != 4 or ms.ndim != 4:\r\n            raise ValueError("Expected NCHW tensors for pan, lms, and ms")\r\n        n, channels, h, w = lms.shape\r\n        if channels != self.channels or h % 4 or w % 4 or min(h, w) < 4:\r\n            raise ValueError(f"Invalid LMS shape: {tuple(lms.shape)}")\r\n        if pan.shape != (n, self.guide_channels, h, w) or ms.shape != (n, channels, h // 4, w // 4):\r\n            raise ValueError("Expected guide at LMS resolution and MS at 1/4 resolution")\r\n\r\n        pan_down_up = self.upsample1(self.downsample1(pan))\r\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\r\n        features = torch.cat([lms, pan, pan_updown], dim=1)\r\n        features = self.backbone(self.cov2t64(features))\r\n        res = self.conv64t48(features) + lms\r\n\r\n        pan_ms = self._attend(pan, res, lms, self.SSA_blocks, self.conv48tnum1, self.prelu1)\r\n        res = res + pan_ms\r\n\r\n        res_half = self.downsample100(res)\r\n        ms_half = self.upsample100(ms)\r\n        pan_half = self.downsample100(pan)\r\n        pan_ms = self._attend(pan_half, res_half, ms_half, self.SSA_blocks1, self.conv48tnum2, self.prelu2)\r\n        res_half = res_half + pan_ms\r\n\r\n        res_quarter = self.downsample200(res_half)\r\n        pan_quarter = self.downsample2(pan)\r\n        pan_ms = self._attend(pan_quarter, res_quarter, ms, self.SSA_blocks2, self.conv48tnum3, self.prelu3)\r\n\r\n        output = self.conv2ctc1(torch.cat([ms, pan_ms], dim=1))\r\n        output = self.conv2ctc2(torch.cat([self.upsample101(output), res_half], dim=1))\r\n        output = self.conv2ctc3(torch.cat([self.upsample102(output), res], dim=1))\r\n        return output\r\n', 'SSA-MRN/src/ssamrn/data/pancollection.py': '"""Read PanCollection H5 files without changing their original arrays."""\r\n\r\nfrom pathlib import Path\r\n\r\nimport h5py\r\nimport numpy as np\r\nimport torch\r\nfrom torch.utils.data import Dataset\r\n\r\n\r\nSENSOR_MAX = {"QB": 2047.0, "WV3": 2047.0, "GF2": 1023.0, "WV2": 2047.0}\r\nREQUIRED_KEYS = ("pan", "lms", "ms", "gt")\r\n\r\n\r\ndef inspect_h5(path):\r\n    """Return array metadata; do not load the complete dataset into RAM."""\r\n    with h5py.File(path, "r") as file:\r\n        return {\r\n            key: {"shape": tuple(value.shape), "dtype": str(value.dtype)}\r\n            for key, value in file.items()\r\n            if isinstance(value, h5py.Dataset)\r\n        }\r\n\r\n\r\nclass PanCollectionH5(Dataset):\r\n    """PanCollection reduced-resolution pairs in NCHW layout."""\r\n\r\n    def __init__(self, path, sensor="QB", limit=None):\r\n        self.path = Path(path)\r\n        self.sensor = sensor.upper()\r\n        if self.sensor not in SENSOR_MAX:\r\n            raise ValueError(f"Unknown sensor: {sensor}")\r\n        metadata = inspect_h5(self.path)\r\n        missing = set(REQUIRED_KEYS) - metadata.keys()\r\n        if missing:\r\n            raise ValueError(f"Missing H5 datasets: {sorted(missing)}")\r\n\r\n        shapes = {key: metadata[key]["shape"] for key in REQUIRED_KEYS}\r\n        if any(len(shape) != 4 for shape in shapes.values()):\r\n            raise ValueError(f"Expected NCHW arrays, got {shapes}")\r\n        n, channels, h, w = shapes["gt"]\r\n        if not n or min(h, w) <= 0 or h % 4 or w % 4:\r\n            raise ValueError(f"Invalid GT shape: {shapes[\'gt\']}")\r\n        if shapes["lms"] != shapes["gt"]:\r\n            raise ValueError(f"LMS and GT shapes differ: {shapes}")\r\n        if shapes["pan"] != (n, 1, h, w):\r\n            raise ValueError(f"PAN shape differs from GT: {shapes}")\r\n        if shapes["ms"] != (n, channels, h // 4, w // 4):\r\n            raise ValueError(f"MS should be 4x lower-resolution: {shapes}")\r\n        if limit is not None and limit < 1:\r\n            raise ValueError("limit must be positive")\r\n        self.length = min(n, limit) if limit is not None else n\r\n        self.channels = channels\r\n        self._file = None\r\n\r\n    def __len__(self):\r\n        return self.length\r\n\r\n    def __getitem__(self, index):\r\n        if index < 0 or index >= self.length:\r\n            raise IndexError(index)\r\n        if self._file is None:\r\n            self._file = h5py.File(self.path, "r")\r\n        scale = SENSOR_MAX[self.sensor]\r\n        sample = {}\r\n        for key in REQUIRED_KEYS:\r\n            array = np.asarray(self._file[key][index], dtype=np.float32)\r\n            if not np.isfinite(array).all():\r\n                raise ValueError(f"Non-finite {key} at index {index}")\r\n            sample[key] = torch.from_numpy(array / scale)\r\n        return sample\r\n\r\n    def __getstate__(self):\r\n        state = self.__dict__.copy()\r\n        state["_file"] = None\r\n        return state\r\n\r\n    def close(self):\r\n        if getattr(self, "_file", None) is not None:\r\n            self._file.close()\r\n            self._file = None\r\n\r\n    def __del__(self):\r\n        self.close()\r\n', 'SSA-MRN/references/upstream/network.py': 'import torch\r\nimport torch.nn as nn\r\nimport torch.nn.functional as F\r\n\r\n\r\nclass ResBlock(nn.Module):\r\n    def __init__(self, in_channels):\r\n        super(ResBlock, self).__init__()\r\n        self.conv1 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\r\n        self.bn1 = nn.BatchNorm2d(in_channels)\r\n        self.conv2 = nn.Conv2d(in_channels, in_channels, kernel_size=3, padding=1, bias=False)\r\n        self.bn2 = nn.BatchNorm2d(in_channels)\r\n\r\n    def forward(self, x):\r\n        residual = x\r\n        out = self.conv1(x)\r\n        out = F.relu(self.bn1(out))\r\n        out = self.conv2(out)\r\n        out = self.bn2(out)\r\n        out += residual\r\n        out = F.relu(out)\r\n        return out\r\n\r\n\r\nclass Resbackbone(nn.Module):\r\n    def __init__(self, in_channels):\r\n        super(Resbackbone, self).__init__()\r\n        channel = 64\r\n        self.conv1 = nn.Conv2d(in_channels=in_channels, out_channels=channel, kernel_size=3, padding=1, stride=1,\r\n                               bias=True)\r\n\r\n        self.res1 = ResBlock(channel)\r\n        self.res2 = ResBlock(channel)\r\n        self.res3 = ResBlock(channel)\r\n        self.res4 = ResBlock(channel)\r\n\r\n        self.backbone = nn.Sequential(\r\n            self.res1,\r\n            self.res2,\r\n            self.res3,\r\n            self.res4,\r\n\r\n        )\r\n        self.relu = nn.ReLU(inplace=True)\r\n        self.conv2 = nn.Conv2d(in_channels=channel, out_channels=1, stride=1, kernel_size=3, padding=1,\r\n                               bias=True)\r\n\r\n    def forward(self, x):\r\n        x = self.relu(self.conv1(x))\r\n        x = self.backbone(x)\r\n        x = self.conv2(x)\r\n        return x\r\n\r\n\r\nclass Resblock(nn.Module):\r\n    def __init__(self):\r\n        super(Resblock, self).__init__()\r\n\r\n        channel = 64\r\n\r\n        self.conv20 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\r\n                                bias=True)\r\n        self.conv21 = nn.Conv2d(in_channels=channel, out_channels=channel, padding=1, kernel_size=3, stride=1,\r\n                                bias=True)\r\n        self.relu = nn.ReLU(\r\n            inplace=True) \r\n    def forward(self, x):\r\n        rs1 = self.relu(self.conv20(x))\r\n        rs2 = self.conv21(rs1)  \r\n        # print(f"rs2:{rs2.shape},x:{x.shape}")\r\n        rs = torch.add(x, rs2) \r\n        return rs\r\n\r\n\r\nclass SSA(nn.Module):\r\n    def __init__(self,channels):\r\n        super(SSA, self).__init__()\r\n\r\n        self.fixed  = 4\r\n\r\n\r\n        self.conv1t6 = nn.Conv2d(in_channels=1, out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\r\n                                 bias=True)\r\n        self.conv6t12 = nn.Conv2d(in_channels=6, out_channels=12, kernel_size=3, stride=1, padding=1,\r\n                                  bias=True)\r\n        self.conv6t6 = nn.Conv2d(in_channels=self.fixed , out_channels=self.fixed , kernel_size=3, stride=1, padding=1,\r\n                                 bias=True)\r\n        self.relu = nn.ReLU()\r\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\r\n                                   padding=1, bias=True)\r\n\r\n    def forward(self, pan, ms_pro):  # ms_pro 6xhxw  pan 1xhxw\r\n        pan_guide = self.relu(self.conv1t6(pan))\r\n        pan_guide = self.conv6t6(pan_guide)  # 6*h*w\r\n        ms_pro = self.conv7t6_3(ms_pro)\r\n        # pan reshape -> 6xhw\r\n        # ms_pro reshape -> 6xhw  -> transpose > 6xwh\r\n        b, c, h, w = ms_pro.size()\r\n        pan_reshape = pan_guide.view(b, c, -1)  # 6xhw\r\n        ms_pro_transpose = ms_pro.permute(0, 1, 3, 2)\r\n        ms_pro_reshape = ms_pro_transpose.reshape(b, c, -1)  # 6xhw\r\n        # print(ms_pro_reshape.shape)\r\n        # ms使用了转置\r\n\r\n        # pan_matrix * ms_pro_matrix -> 6xhwxwh -> softmax ->6xhxw\r\n        pan_matrix = torch.mul(pan_reshape, ms_pro_reshape)  # b x c x hw x wh\r\n        # print(pan_matrix.shape)\r\n        pan_matrix = pan_matrix.view(b, c, h, w)\r\n        # print(pan_matrix.shape)\r\n        pan_matrix = pan_matrix.permute(0, 1, 3, 2)\r\n        pan_matrix = pan_matrix.contiguous().view(b, c, -1)\r\n       \r\n        pan_matrix = F.softmax(pan_matrix, dim=-1)\r\n        # print(pan_matrix.shape)\r\n\r\n        # transpose_R * ms_pro_matrix -> 6xhwxwh -> reshape -> output= 6xhxw\r\n        output = torch.mul(pan_reshape, pan_matrix)  # b x c x hw\r\n        output = output.contiguous().view(b, c, h, w)  # reshape to 6xhxw\r\n\r\n        # print(f"res{res.shape}")\r\n        return output\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\nclass PansharpeningNet(nn.Module):\r\n    def __init__(self, channels):\r\n        super(PansharpeningNet, self).__init__()\r\n\r\n        self.fixed = 4\r\n\r\n        # Downsampling and Upsampling layers\r\n        self.downsample1 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\r\n        self.downsample2 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\r\n        self.upsample1 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\r\n        self.upsample2 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\r\n        self.downsample200 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\r\n        # Feature extraction and fusion layers with individual names\r\n        self.prelu1 = nn.PReLU()\r\n        self.prelu2 = nn.PReLU()\r\n        self.prelu3 = nn.PReLU()\r\n\r\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\r\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\r\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\r\n\r\n        self.conv1t64_pan = nn.Conv2d(1, 64, kernel_size=3, padding=1)\r\n        self.conv64tnum_pan = nn.Conv2d(64, channels, kernel_size=3, padding=1)\r\n\r\n        self.convnum3tnum1 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\r\n        self.convnum3tnum2 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\r\n        self.convnum3tnum3 = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\r\n\r\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n        self.conv48tnum3 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n\r\n        self.conv7t6_1 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\r\n                                   padding=1, bias=True)\r\n        self.conv7t6_2 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\r\n                                   padding=1, bias=True)\r\n        self.conv7t6_3 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1,\r\n                                   padding=1, bias=True)\r\n\r\n        self.conv2ctc1 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                   bias=True)\r\n        self.conv2ctc2 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                   bias=True)\r\n        self.conv2ctc3 = nn.Conv2d(in_channels=channels * 2, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                   bias=True)\r\n\r\n        self.SSA_blocks = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\r\n\r\n        self.SSA_blocks1 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\r\n        self.SSA_blocks2 = nn.ModuleList([SSA(channels=channels) for _ in range(channels)])\r\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\r\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\r\n                                 bias=True)\r\n\r\n        self.res1 = Resblock()\r\n        self.res2 = Resblock()\r\n        self.res3 = Resblock()\r\n        self.res4 = Resblock()\r\n\r\n        self.backbone = nn.Sequential(\r\n                self.res1,\r\n                self.res2,\r\n                self.res3,\r\n                self.res4,\r\n            )\r\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\r\n        self.fixed = 4;\r\n\r\n        # Downsampling and Upsampling layers\r\n        self.downsample = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\r\n        self.upsample = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\r\n        self.downsample1 = nn.Upsample(scale_factor=0.25, mode=\'bilinear\', align_corners=True)\r\n        self.upsample1 = nn.Upsample(scale_factor=4, mode=\'bilinear\', align_corners=True)\r\n        self.upsample100 = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\r\n        self.downsample100 = nn.Upsample(scale_factor=0.5, mode=\'bilinear\', align_corners=True)\r\n        self.upsample101  = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\r\n        self.upsample102\\\r\n            = nn.Upsample(scale_factor=2, mode=\'bilinear\', align_corners=True)\r\n        # Fusion layers\r\n        self.resblock = Resblock()\r\n        self.prelu = nn.PReLU()\r\n        self.conv1t64 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\r\n        self.conv64tnum = nn.Conv2d(64, channels, kernel_size=3, padding=1)\r\n        self.convnumt64 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\r\n\r\n        self.conv1t64bf2 = nn.Conv2d(1, 64, kernel_size=3, padding=1)\r\n        self.conv64tnumbf2 = nn.Conv2d(64, channels, kernel_size=3, padding=1)\r\n        self.convnumt64bf2 = nn.Conv2d(channels, 64, kernel_size=3, padding=1)\r\n\r\n        self.convnumtnum = nn.Conv2d(channels * 3, channels * 3, kernel_size=3, padding=1)\r\n        self.convctc1 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc1\r\n        self.convctc2 = nn.Conv2d(channels, channels, kernel_size=3, padding=1)  # convctc2\r\n        self.convnum3tnum = nn.Conv2d(channels * 3, channels, kernel_size=3, padding=1)\r\n        self.relu = nn.ReLU()\r\n\r\n        self.conv2 = nn.Conv2d(in_channels=channels, out_channels=channels * 6, stride=1, kernel_size=3, padding=1,\r\n                               bias=True)\r\n\r\n        self.SSA_blocks = nn.ModuleList(\r\n            [SSA(channels=channels) for _ in range(channels)])  # Adding multi-scale blocks\r\n\r\n        self.conv48tnum1 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n        self.conv48tnum2 = nn.Conv2d(in_channels=self.fixed * channels, out_channels=channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n\r\n        self.conv48t48_1 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n        self.conv48t48_2 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                     bias=True)\r\n        self.conv48t48_3 = nn.Conv2d(in_channels=6 * channels, out_channels=6 * channels, kernel_size=3, stride=1,\r\n                                     padding=1, bias=True)\r\n\r\n        self.conv7t6 = nn.Conv2d(in_channels=channels + 1, out_channels=self.fixed, kernel_size=3, stride=1, padding=1,\r\n                                 bias=True)\r\n\r\n        self.convnum3tn64 = nn.Conv2d(in_channels=channels * 3, out_channels=64, kernel_size=3, stride=1, padding=1,\r\n                                      bias=True)\r\n\r\n        self.group_size = 6 \r\n        self.channels = channels\r\n        self.cov2t64 = nn.Conv2d(in_channels=2 + channels, out_channels=64, kernel_size=3, stride=1, padding=1,\r\n                                 bias=True)\r\n        self.conv64t48 = nn.Conv2d(in_channels=64, out_channels=channels, kernel_size=3, stride=1, padding=1, bias=True)\r\n        self.conv1t1 = nn.Conv2d(in_channels=1, out_channels=1, kernel_size=3, stride=1, padding=1, bias=True)\r\n\r\n        self.convnumt48 = nn.Conv2d(in_channels=channels, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                    bias=True)\r\n\r\n        self.relu = nn.ReLU(inplace=True)\r\n        self.conv8t4 = nn.Conv2d(in_channels=8, out_channels=channels, kernel_size=3, stride=1, padding=1,\r\n                                    bias=True)\r\n\r\n\r\n\r\n   \r\n    def forward(self, pan, lms):\r\n        # Stage 1: Downsample and upsample each input\r\n        pan_down_up = self.upsample1(self.downsample1(pan))\r\n        pan_updown = self.prelu(self.conv1t1(pan_down_up))\r\n        input = torch.cat([lms, pan, pan_updown], dim=1)\r\n\r\n        y = self.cov2t64(input)\r\n        y = self.backbone(y)\r\n        y1 = self.conv64t48(y)\r\n        rs = y1 + lms\r\n\r\n        # Process input channels separately\r\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\r\n        split_ms = [lms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\r\n\r\n        outputs = []\r\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks):\r\n            x = torch.cat([rs, ms_channel], dim=1)\r\n\r\n            ms_one = ssa(pan, x)\r\n            outputs.append(ms_one)\r\n\r\n        pan_ms = torch.cat(outputs, dim=1)\r\n        pan_ms = self.prelu1(self.conv48tnum1(pan_ms))\r\n        fsm_msb = rs + pan_ms\r\n        res = fsm_msb\r\n\r\n        res_down = self.downsample100(res)\r\n\r\n        # Stage 2: MS upsample and next stage fusion\r\n        ms_up = self.upsample100(ms)\r\n        rs = res_down\r\n\r\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\r\n        split_ms = [ms_up[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\r\n\r\n        outputs = []\r\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks1):\r\n            x = torch.cat([rs, ms_channel], dim=1)\r\n\r\n            pan_down = self.downsample100(pan)\r\n            ms_one = ssa(pan_down, x)\r\n            outputs.append(ms_one)\r\n\r\n        pan_ms = torch.cat(outputs, dim=1)\r\n        pan_ms = self.prelu2(self.conv48tnum2(pan_ms))\r\n        fsm_msb = rs + pan_ms\r\n        res_down = fsm_msb\r\n\r\n        # Stage 3: Small scale stage\r\n        res_small = self.downsample200(res_down)\r\n        rs = res_small\r\n\r\n        split_input = [rs[:, i:i + self.group_size, :, :] for i in range(0, 48, self.group_size)]\r\n        split_ms = [ms[:, i, :, :].unsqueeze(1) for i in range(self.channels)]\r\n\r\n        outputs = []\r\n        for input_channel, ms_channel, ssa in zip(split_input, split_ms, self.SSA_blocks2):\r\n            x = torch.cat([rs, ms_channel], dim=1)\r\n\r\n            pan_down = self.downsample2(pan)\r\n            ms_one = ssa(pan_down, x)\r\n            outputs.append(ms_one)\r\n\r\n        pan_ms = torch.cat(outputs, dim=1)\r\n        pan_ms = self.prelu3(self.conv48tnum3(pan_ms))\r\n        res_small = pan_ms\r\n\r\n        # Output processing\r\n        ms_output = ms\r\n        ms_output = torch.cat([ms_output, res_small], dim=1)\r\n        ms_output = self.conv2ctc1(ms_output)\r\n\r\n        ms_output = self.upsample101(ms_output)\r\n        ms_output = torch.cat([ms_output, res_down], dim=1)\r\n        ms_output = self.conv2ctc2(ms_output)\r\n\r\n        ms_output = self.upsample102(ms_output)\r\n        ms_output = torch.cat([ms_output, res], dim=1)\r\n        ms_output = self.conv2ctc3(ms_output)\r\n\r\n\r\n\r\n\r\n        return ms_output\r\n'}
